package com.boomerangbandits.services;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.models.PluginConfigResponse;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Map;
import java.util.function.Supplier;

@Singleton
public class FeatureFlagService {

    @Inject
    private ConfigSyncService configSyncService;

    @Inject
    private BoomerangBanditsConfig config;

    public boolean isEnabled(String featureName, Supplier<Boolean> userConfigGetter) {
        PluginConfigResponse latestConfig = configSyncService.getLatestConfig();
        if (latestConfig == null) {
            return userConfigGetter.get();
        }

        Map<String, Boolean> features = latestConfig.getFeatures();
        if (features == null || !features.containsKey(featureName)) {
            return userConfigGetter.get();
        }

        Boolean serverEnabled = features.get(featureName);
        if (Boolean.FALSE.equals(serverEnabled)) {
            return false;
        }

        return userConfigGetter.get();
    }

    public boolean isCofferSoundEnabled() {
        return isEnabled("cofferDepositSound", config::cofferDepositSound);
    }

    public boolean isEventOverlayEnabled() {
        return isEnabled("eventOverlay", config::showEventOverlay);
    }

    public boolean isEasterEggsEnabled() {
        return isEnabled("easterEggs", config::enableEasterEggs);
    }

    public boolean isBountyTrackingEnabled() {
        return isEnabled("bountyTracking", () -> true);
    }
}

package com.boomerangbandits.services;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Delivers announcements as in-game chat messages via ChatMessageManager.
 * <p>
 * Complements the sidebar display in HomePanel — players see announcements
 * even when the plugin panel isn't open.
 * <p>
 * Deduplication: announcements are tracked by content hash so the same
 * message is never shown twice per session (survives config sync polls).
 * Resets on logout so returning players see current announcements fresh.
 */
@Slf4j
@Singleton
public class InGameAnnouncementService {

    private static final String PREFIX = "[Boomerang Bandits]";

    @Inject
    private ChatMessageManager chatMessageManager;

    /**
     * Content hashes of announcements already delivered this session.
     * Using content hash (not index) so reordering the list on the backend
     * doesn't cause duplicate deliveries.
     */
    private final Set<Integer> deliveredHashes = new HashSet<>();

    /**
     * Deliver any new announcements to in-game chat.
     * Safe to call repeatedly — only undelivered messages are shown.
     *
     * @param announcements current announcement list from config
     */
    public void deliverAnnouncements(List<String> announcements) {
        if (announcements == null || announcements.isEmpty()) {
            return;
        }

        for (String message : announcements) {
            if (message == null || message.trim().isEmpty()) {
                continue;
            }

            int hash = message.hashCode();
            if (deliveredHashes.contains(hash)) {
                continue;
            }

            chatMessageManager.queue(QueuedMessage.builder()
                    .type(ChatMessageType.BROADCAST)
                    .runeLiteFormattedMessage(
                            "<col=FFD700>" + PREFIX + "</col> " + message)
                    .build());

            deliveredHashes.add(hash);
            log.debug("Delivered in-game announcement: {}", truncate(message));
        }
    }

    /**
     * Reset tracking state. Call on logout so returning players
     * see current announcements fresh on their next session.
     */
    public void reset() {
        deliveredHashes.clear();
    }

    private static String truncate(String s) {
        return s.length() > 60 ? s.substring(0, 60) + "..." : s;
    }
}

package com.boomerangbandits.services;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.ClanApiService;
import com.boomerangbandits.api.models.PluginConfigResponse;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.TimeUnit;

/**
 * Periodically polls the backend for remote plugin configuration.
 * <p>
 * Lifecycle:
 * 1. Plugin calls start() AFTER successful authentication
 * 2. Polls GET /api/plugin/config every configSyncInterval seconds
 * 3. Updates hidden config items in RuneLite's ConfigManager
 * 4. UI reacts to ConfigChanged events automatically
 * 5. Plugin calls stop() on shutdown
 * <p>
 * Does NOT start before authentication. The memberCode is required.
 */
@Slf4j
@Singleton
public class ConfigSyncService {

    @Inject
    private ClanApiService clanApi;
    @Inject
    private BoomerangBanditsConfig config;
    @Inject
    private ConfigManager configManager;
    @Inject
    private Gson gson;

    private ScheduledFuture<?> syncTask;

    @Getter
    private volatile PluginConfigResponse latestConfig;

    private static final int DEFAULT_WOM_LIST_POLLING_INTERVAL_MINUTES = 10;
    private static final int DEFAULT_WOM_DETAIL_POLLING_INTERVAL_MINUTES = 5;
    private static final int MIN_WOM_POLLING_INTERVAL_MINUTES = 1;
    private static final int MAX_WOM_POLLING_INTERVAL_MINUTES = 1440;

    @Getter
    private volatile int womListPollingIntervalMinutes = DEFAULT_WOM_LIST_POLLING_INTERVAL_MINUTES;

    @Getter
    private volatile int womDetailPollingIntervalMinutes = DEFAULT_WOM_DETAIL_POLLING_INTERVAL_MINUTES;

    /**
     * Optional callback invoked on every successful config sync.
     * Used by the plugin to update UI sections (bounties, features, renames)
     * that live in memory only and don't trigger ConfigChanged events.
     */
    @Setter
    private volatile Runnable onConfigUpdated;

    /**
     * Start periodic config sync. Call only after authentication succeeds.
     *
     * @param executor the plugin's shared ScheduledExecutorService
     */
    public void start(ScheduledExecutorService executor) {
        if (syncTask != null && !syncTask.isDone()) {
            log.debug("ConfigSyncService already running");
            return;
        }

        int intervalSeconds = config.configSyncInterval();

        // Small initial delay to allow the UI and session to stabilize after login (Finding B4)
        syncTask = executor.scheduleAtFixedRate(
                this::syncConfig,
                5,
                intervalSeconds,
                TimeUnit.SECONDS
        );

        log.info("Config sync started (interval: {}s)", intervalSeconds);
    }

    /**
     * Stop periodic config sync.
     */
    public void stop() {
        if (syncTask != null) {
            syncTask.cancel(false);
            syncTask = null;
        }

        log.info("Config sync stopped");
    }

    /**
     * Force an immediate config sync outside the normal schedule.
     */
    public void syncNow() {
        syncConfig();
    }

    private void syncConfig() {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            log.debug("Skipping config sync — not authenticated");
            return;
        }

        clanApi.fetchPluginConfig(memberCode,
                this::applyConfig,
                error -> log.warn("Config sync failed: {}", error)
        );
    }

    private void applyConfig(PluginConfigResponse remoteConfig) {
        this.latestConfig = remoteConfig;
        int rawListInterval = remoteConfig.getWomListPollingIntervalMinutes();
        this.womListPollingIntervalMinutes = rawListInterval > 0
                ? Math.max(MIN_WOM_POLLING_INTERVAL_MINUTES, Math.min(rawListInterval, MAX_WOM_POLLING_INTERVAL_MINUTES))
                : DEFAULT_WOM_LIST_POLLING_INTERVAL_MINUTES;
        int rawDetailInterval = remoteConfig.getWomDetailPollingIntervalMinutes();
        this.womDetailPollingIntervalMinutes = rawDetailInterval > 0
                ? Math.max(MIN_WOM_POLLING_INTERVAL_MINUTES, Math.min(rawDetailInterval, MAX_WOM_POLLING_INTERVAL_MINUTES))
                : DEFAULT_WOM_DETAIL_POLLING_INTERVAL_MINUTES;
        setIfChanged("announcementMessage", remoteConfig.getAnnouncementMessage());
        setIfChanged("rollCallActive", String.valueOf(remoteConfig.isRollCallActive()));
        setIfChanged("websiteUrl", remoteConfig.getWebsiteUrl());
        setIfChanged("discordUrl", remoteConfig.getDiscordUrl());
        setIfChanged("womListPollingIntervalMinutes", String.valueOf(this.womListPollingIntervalMinutes));
        setIfChanged("womDetailPollingIntervalMinutes", String.valueOf(this.womDetailPollingIntervalMinutes));

        // Serialize announcements list to JSON for config storage
        List<String> announcements = remoteConfig.getAnnouncements();
        setIfChanged("announcements", gson.toJson(
                announcements != null ? announcements : Collections.emptyList()));

        // Store the Dink dynamic config URL in our own config so the UI can display it.
        // Users can copy it from the Clan Hub panel and paste it into Dink's settings manually.
        String dinkConfigUrl = remoteConfig.getDinkConfigUrl();
        if (dinkConfigUrl != null && !dinkConfigUrl.isEmpty()) {
            setIfChanged("dinkConfigUrl", dinkConfigUrl);
        }

        log.debug("Config sync applied successfully");

        // Notify listener for in-memory-only fields (bounties, features, renames)
        Runnable listener = onConfigUpdated;
        if (listener != null) {
            listener.run();
        }
    }

    /**
     * Only update the config value if it actually changed.
     * This prevents unnecessary ConfigChanged events from firing.
     */
    private void setIfChanged(String key, String newValue) {
        if (newValue == null) {
            return;
        }

        String currentValue = configManager.getConfiguration(BoomerangBanditsConfig.GROUP, key);
        if (!newValue.equals(currentValue)) {
            configManager.setConfiguration(BoomerangBanditsConfig.GROUP, key, newValue);
            log.debug("Config updated: {} = {}", key, newValue);
        }
    }
}

package com.boomerangbandits.services;

import com.boomerangbandits.api.WomApiService;
import com.boomerangbandits.api.models.WomCompetition;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Periodically refreshes WOM competition data.
 * <p>
 * Schedule:
 * - Competition list: every 10 minutes
 * - Active competition details: every 5 minutes (only when an active competition exists)
 * <p>
 * Started from BoomerangBanditsPlugin.startUp() AFTER authentication succeeds.
 * Stopped from shutDown().
 */
@Slf4j
@Singleton
public class CompetitionScheduler {

    private final WomApiService womApi;
    private final ConfigSyncService configSyncService;

    private ScheduledFuture<?> listTask;
    private ScheduledFuture<?> detailTask;
    private volatile int currentListIntervalMinutes = -1;
    private volatile int currentDetailIntervalMinutes = -1;

    /**
     * -- GETTER --
     * Get the currently tracked active competition ID.
     * Returns -1 if no active competition.
     */
    // Track the currently active competition ID for detail polling
    @Getter
    private volatile int activeCompetitionId = -1;

    @Inject
    public CompetitionScheduler(WomApiService womApi, ConfigSyncService configSyncService) {
        this.womApi = womApi;
        this.configSyncService = configSyncService;
    }

    /**
     * Start periodic competition polling.
     * Call from plugin startUp() after auth succeeds.
     *
     * @param executor the plugin's shared ScheduledExecutorService
     */
    public synchronized void start(ScheduledExecutorService executor) {
        log.debug("Starting CompetitionScheduler tasks...");

        int listIntervalMinutes = configSyncService.getWomListPollingIntervalMinutes();
        int detailIntervalMinutes = configSyncService.getWomDetailPollingIntervalMinutes();

        if (listTask != null && !listTask.isDone() && detailTask != null && !detailTask.isDone()) {
            if (listIntervalMinutes == currentListIntervalMinutes && detailIntervalMinutes == currentDetailIntervalMinutes) {
                return;
            }
            log.info("Competition polling interval changed (list: {}m -> {}m, detail: {}m -> {}m), restarting",
                    currentListIntervalMinutes,
                    listIntervalMinutes,
                    currentDetailIntervalMinutes,
                    detailIntervalMinutes);
            stop();
        }

        listTask = executor.scheduleAtFixedRate(
                this::refreshCompetitionList,
                0,
                listIntervalMinutes,
                TimeUnit.MINUTES
        );
        currentListIntervalMinutes = listIntervalMinutes;
        log.debug("Scheduled competition list task ({} minutes)", listIntervalMinutes);

        detailTask = executor.scheduleAtFixedRate(
                this::refreshActiveCompetition,
                30,
                detailIntervalMinutes * 60L,
                TimeUnit.SECONDS
        );
        currentDetailIntervalMinutes = detailIntervalMinutes;
        log.debug("Scheduled competition detail task ({} minutes)", detailIntervalMinutes);

        log.info("CompetitionScheduler started");
    }

    /**
     * Stop all polling tasks.
     * Call from plugin shutDown().
     */
    public synchronized void stop() {
        if (listTask != null) {
            listTask.cancel(false);
            listTask = null;
        }
        if (detailTask != null) {
            detailTask.cancel(false);
            detailTask = null;
        }
        currentListIntervalMinutes = -1;
        currentDetailIntervalMinutes = -1;
        activeCompetitionId = -1;
        log.info("CompetitionScheduler stopped");
    }

    private void refreshCompetitionList() {
        log.debug("refreshCompetitionList() called - fetching from WOM API");
        womApi.fetchCompetitions(
                competitions -> {
                    log.debug("Received {} competitions from WOM API", competitions.size());
                    // Find the first ongoing competition for detail polling
                    int ongoingCount = 0;
                    int upcomingCount = 0;
                    int finishedCount = 0;
                    for (WomCompetition comp : competitions) {
                        String status = comp.getStatus();
                        log.debug("Competition: {} - Status: {} (starts: {}, ends: {})",
                                comp.getTitle(), status, comp.getStartsAt(), comp.getEndsAt());

                        if (comp.isOngoing()) {
                            if (activeCompetitionId == -1) {
                                activeCompetitionId = comp.getId();
                                log.info("✅ Set active competition: {} (ID: {})", comp.getTitle(), comp.getId());
                            }
                            ongoingCount++;
                        } else if (comp.isUpcoming()) {
                            upcomingCount++;
                        } else if (comp.isFinished()) {
                            finishedCount++;
                        }
                    }
                    if (ongoingCount == 0) {
                        activeCompetitionId = -1;
                        log.debug("No ongoing competitions found");
                    }
                    log.info("✅ Competition list fetched: {} total ({} ongoing, {} upcoming, {} finished)",
                            competitions.size(), ongoingCount, upcomingCount, finishedCount);
                },
                error -> log.warn("Failed to refresh competition list", error)
        );
    }

    private void refreshActiveCompetition() {
        int compId = activeCompetitionId;
        if (compId == -1) {
            return; // No active competition
        }

        womApi.fetchCompetitionDetails(
                compId,
                competition -> log.debug("Refreshed active competition: {}", competition.getTitle()),
                error -> log.warn("Failed to refresh competition {}", compId, error)
        );
    }

}

package com.boomerangbandits.services;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import java.util.regex.Pattern;

/**
 * Listens for clan chat coffer deposit messages and plays a sound effect.
 *
 * <p>Matches messages of the form:
 * "{RSN} has deposited {amount} coins into the coffer."
 *
 * <p>Sound playback delegates to {@link AudioPlayer} (RuneLite's approved audio API).
 */
@Slf4j
public class CofferDepositSoundService {

    /**
     * Matches clan chat coffer deposit messages.
     * Examples:
     * "Zezima has deposited 1,000,000 coins into the coffer."
     * "Some Player has deposited 500 coins into the coffer."
     */
    private static final Pattern COFFER_DEPOSIT_PATTERN = Pattern.compile(
            ".+ has deposited [\\d,]+ coins into the coffer\\.",
            Pattern.CASE_INSENSITIVE
    );

    @Inject
    private AudioPlayer audioPlayer;

    @Inject
    private FeatureFlagService featureFlagService;

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!featureFlagService.isCofferSoundEnabled()) {
            return;
        }

        // Only listen to clan chat messages
        if (event.getType() != ChatMessageType.CLAN_MESSAGE
                && event.getType() != ChatMessageType.FRIENDSCHAT) {
            return;
        }

        String message = event.getMessage();
        if (message == null) {
            return;
        }

        // Strip any HTML tags RuneLite may inject (e.g. <col=...>text</col>)
        String stripped = message.replaceAll("<[^>]*>", "").trim();

        if (COFFER_DEPOSIT_PATTERN.matcher(stripped).matches()) {
            log.debug("Coffer deposit detected: {}", stripped);
            playDepositSound();
        }
    }

    // ======================================================================
    // SOUND PLAYBACK
    // ======================================================================

    /**
     * Plays the bundled coffer-deposit.wav via RuneLite's AudioPlayer.
     */
    private void playDepositSound() {
        try {
            audioPlayer.play(getClass(), "/com/boomerangbandits/coffer-deposit.wav", 0f);
        } catch (Exception e) {
            log.warn("Could not play coffer deposit sound", e);
        }
    }
}

package com.boomerangbandits.services;

/*
 * Attendance tracking logic adapted from:
 *   Clan Event Attendance by Jonathan Rousseau (JoRouss)
 *   https://github.com/JoRouss/runelite-ClanEventAttendance
 *   BSD 2-Clause License
 *
 * Changes from original:
 *  - Removed panel/UI, config, clipboard, and text-generation code
 *  - Tracks clan chat only (no friends chat option needed)
 *  - Exposes structured AttendanceEntry list instead of formatted text
 *  - Integrated into BoomerangBanditsPlugin event lifecycle
 */

import com.boomerangbandits.api.models.AttendanceEntry;
import com.boomerangbandits.util.GameModeGuard;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Tracks clan member attendance during an in-game event.
 * <p>
 * Usage:
 * startEvent()  — call when admin starts the event
 * stopEvent()   — call when admin stops; returns the attendance list
 * onGameTick()  — call every game tick while running
 * onPlayerSpawned/Despawned/ClanMemberJoined/Left — forward from plugin
 */
@Slf4j
@Singleton
public class EventAttendanceTracker {

    /**
     * Minimum seconds a member must be present to count as "attended".
     */
    public static final int DEFAULT_PRESENT_THRESHOLD_SECONDS = 60 * 10; // 10 min
    /**
     * Seconds after event start before a member is considered "late".
     */
    public static final int DEFAULT_LATE_THRESHOLD_SECONDS = 60 * 5;     // 5 min
    // keyed by normalized (Jagex) lowercase name
    private final Map<String, MemberAttendance> buffer = new TreeMap<>();
    @Inject
    private Client client;
    @Inject
    private GameModeGuard gameModeGuard;
    @Getter
    private boolean running = false;

    private int eventStartTick;
    private int eventStopTick;

    // Delay one tick after login/hop before scanning, same as original
    private int scanDelay = 0;

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    public void startEvent() {
        if (!gameModeGuard.isStandardWorld()) {
            log.warn("[Attendance] Cannot start event — non-standard world");
            return;
        }
        buffer.clear();
        eventStartTick = client.getTickCount();
        running = true;
        scanDelay = 1;
        log.info("[Attendance] Event started at tick {}", eventStartTick);
    }

    /**
     * Stop the event and return the structured attendance list.
     *
     * @param presentThresholdSeconds members below this are still included but flagged
     * @param lateThresholdSeconds    members who arrived after this are flagged as late
     */
    public List<AttendanceEntry> stopEvent(int presentThresholdSeconds, int lateThresholdSeconds) {
        // Compile any still-present members
        for (String key : buffer.keySet()) {
            compileTicks(key);
        }
        eventStopTick = client.getTickCount();
        running = false;

        List<AttendanceEntry> entries = new ArrayList<>(buffer.size());
        for (MemberAttendance ma : buffer.values()) {
            int secondsPresent = ticksToSeconds(ma.ticksTotal);
            int secondsLate = ticksToSeconds(ma.ticksLate);
            boolean late = secondsLate > lateThresholdSeconds;
            boolean meetsThreshold = secondsPresent >= presentThresholdSeconds;
            entries.add(new AttendanceEntry(
                    ma.playerName,
                    secondsPresent,
                    late ? secondsLate : 0,
                    meetsThreshold
            ));
        }

        log.info("[Attendance] Event stopped. {} members tracked, {} meet threshold.",
                entries.size(),
                entries.stream().filter(AttendanceEntry::isMeetsThreshold).count());

        return entries;
    }

    /**
     * Convenience overload using defaults.
     */
    public List<AttendanceEntry> stopEvent() {
        return stopEvent(DEFAULT_PRESENT_THRESHOLD_SECONDS, DEFAULT_LATE_THRESHOLD_SECONDS);
    }

    public int getEventDurationSeconds() {
        int endTick = running ? client.getTickCount() : eventStopTick;
        return ticksToSeconds(endTick - eventStartTick);
    }

    public int getMemberCount() {
        return buffer.size();
    }

    // -------------------------------------------------------------------------
    // Event handlers — forward these from BoomerangBanditsPlugin
    // -------------------------------------------------------------------------

    public void onGameTick() {
        if (!running) return;

        if (scanDelay == 0) {
            // Refresh clan member list and scan visible players
            if (client.getClanChannel() != null) {
                for (final Player player : client.getTopLevelWorldView().players()) {
                    if (player == null) continue;
                    if (isClanMember(player)) {
                        addPlayer(player);
                        unpausePlayer(player.getName());
                    }
                }
            }
        }

        if (scanDelay >= 0) {
            --scanDelay;
        }

        // Accumulate ticks for all tracked members
        for (String key : buffer.keySet()) {
            compileTicks(key);
        }
    }

    public void onPlayerSpawned(Player player) {
        if (!running) return;
        if (!isClanMember(player)) return;
        addPlayer(player);
        unpausePlayer(player.getName());
    }

    public void onPlayerDespawned(Player player) {
        if (!running) return;
        String key = nameToKey(player.getName());
        if (!buffer.containsKey(key)) return;
        compileTicks(player.getName());
        pausePlayer(player.getName());
    }

    public void onClanMemberJoined(ClanChannelMember member) {
        if (!running) return;
        if (member.getWorld() != client.getWorld()) return;

        String memberName = member.getName();
        for (Player player : client.getTopLevelWorldView().players()) {
            if (player == null) continue;
            if (nameToKey(memberName).equals(nameToKey(player.getName()))) {
                addPlayer(player);
                unpausePlayer(player.getName());
                break;
            }
        }
    }

    public void onClanMemberLeft(ClanChannelMember member) {
        if (!running) return;
        if (member.getWorld() != client.getWorld()) return;

        String key = nameToKey(member.getName());
        if (!buffer.containsKey(key)) return;
        compileTicks(member.getName());
        pausePlayer(member.getName());
    }

    public void onHoppingOrLogin() {
        scanDelay = 1;
    }

    // -------------------------------------------------------------------------
    // Internal helpers (ported verbatim from original plugin)
    // -------------------------------------------------------------------------

    private boolean isClanMember(Player player) {
        return player.isClanMember();
    }

    private void addPlayer(Player player) {
        String key = nameToKey(player.getName());
        if (!buffer.containsKey(key)) {
            MemberAttendance ma = new MemberAttendance(
                    player.getName(),
                    client.getTickCount() - eventStartTick, // ticksLate
                    client.getTickCount(),                   // tickActivityStarted
                    0,                                       // ticksTotal
                    false                                    // isPresent
            );
            buffer.put(key, ma);
        }
    }

    private void pausePlayer(String playerName) {
        MemberAttendance ma = buffer.get(nameToKey(playerName));
        if (ma != null) ma.isPresent = false;
    }

    private void unpausePlayer(String playerName) {
        MemberAttendance ma = buffer.get(nameToKey(playerName));
        if (ma == null || ma.isPresent) return;
        ma.isPresent = true;
        ma.tickActivityStarted = client.getTickCount();
    }

    private void compileTicks(String playerName) {
        MemberAttendance ma = buffer.get(nameToKey(playerName));
        if (ma == null || !ma.isPresent) return;
        ma.ticksTotal += client.getTickCount() - ma.tickActivityStarted;
        ma.tickActivityStarted = client.getTickCount();
    }

    private int ticksToSeconds(int ticks) {
        return (int) (ticks * 0.6f);
    }

    private String nameToKey(String name) {
        return Text.toJagexName(name).toLowerCase();
    }

    // -------------------------------------------------------------------------
    // Internal data class
    // -------------------------------------------------------------------------

    private static class MemberAttendance {
        String playerName;
        int ticksLate;
        int tickActivityStarted;
        int ticksTotal;
        boolean isPresent;

        MemberAttendance(String playerName, int ticksLate, int tickActivityStarted,
                         int ticksTotal, boolean isPresent) {
            this.playerName = playerName;
            this.ticksLate = ticksLate;
            this.tickActivityStarted = tickActivityStarted;
            this.ticksTotal = ticksTotal;
            this.isPresent = isPresent;
        }
    }
}

package com.boomerangbandits.services;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.ApiConstants;
import com.boomerangbandits.api.models.RankSyncRequest;
import com.boomerangbandits.api.models.RankSyncResponse;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Service for syncing clan member ranks to the backend.
 * <p>
 * Features:
 * - Collects ranks from ALL clan members (including offline) using ClanSettings
 * - Normalizes rank names to canonical backend values
 * - Filters out bot accounts (names starting with [#)
 * - Batches updates (max 1000 per request)
 * - Rate limiting (3 requests per minute)
 * - Periodic sync (configurable interval)
 * - Manual sync on demand
 * - Detailed logging of rank distribution
 * <p>
 * Implementation follows WiseOldMan's approach:
 * - Uses ClanSettings.getMembers() to get full roster (not just online)
 * - Uses custom titles from ClanSettings.titleForRank() for rank names
 */
@Slf4j
@Singleton
public class ClanRankSyncService {

    private static final int MAX_BATCH_SIZE = 1000;
    private static final int RATE_LIMIT_REQUESTS = 3;
    private static final long RATE_LIMIT_WINDOW_MS = 60_000; // 1 minute
    private static final int DEFAULT_SYNC_INTERVAL_MINUTES = 30;
    private final List<Long> recentRequestTimes = Collections.synchronizedList(new ArrayList<>());
    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private BoomerangBanditsConfig config;
    @Inject
    private @Named("boomerang") OkHttpClient httpClient;
    @Inject
    private Gson gson;
    private ScheduledFuture<?> periodicSyncTask;
    private ScheduledExecutorService executor;
    private volatile String authToken;
    private volatile long accountHash = -1;

    public void setAuthToken(String authToken) {
        this.authToken = authToken;
    }

    public void setAccountHash(long accountHash) {
        this.accountHash = accountHash;
    }

    /**
     * Start periodic rank syncing.
     */
    public void start(ScheduledExecutorService executor) {
        if (periodicSyncTask != null && !periodicSyncTask.isCancelled()) {
            return; // Already running
        }

        this.executor = executor;
        log.info("Starting clan rank sync service (interval: {} minutes)", DEFAULT_SYNC_INTERVAL_MINUTES);

        periodicSyncTask = executor.scheduleAtFixedRate(
                this::syncRanksAsync,
                5, // Initial delay (minutes)
                DEFAULT_SYNC_INTERVAL_MINUTES,
                TimeUnit.MINUTES
        );
    }

    /**
     * Stop periodic syncing.
     */
    public void stop() {
        if (periodicSyncTask != null) {
            periodicSyncTask.cancel(false);
            periodicSyncTask = null;
            log.info("Stopped clan rank sync service");
        }
    }

    /**
     * Manually trigger a rank sync.
     * This is async and will call the callback when complete.
     */
    public void syncRanksManually(Consumer<RankSyncResponse> onSuccess, Consumer<Exception> onError) {
        log.info("Manual rank sync triggered");
        syncRanks(onSuccess, onError);
    }

    /**
     * Async wrapper for periodic sync (no callbacks).
     */
    private void syncRanksAsync() {
        syncRanks(
                response -> log.info("Rank sync complete: {} synced, {} updated, {} unchanged, {} created, {} not found",
                        response.getSynced(), response.getUpdated(), response.getUnchanged(),
                        response.getCreated(),
                        response.getNotFound() != null ? response.getNotFound().size() : 0),
                error -> log.warn("Rank sync failed", error)
        );
    }

    /**
     * Main sync logic - collects ranks and sends to backend.
     */
    private void syncRanks(Consumer<RankSyncResponse> onSuccess, Consumer<Exception> onError) {
        // Check rate limit and record atomically to prevent TOCTOU race
        synchronized (recentRequestTimes) {
            if (!checkRateLimit()) {
                log.warn("Rate limit exceeded - skipping rank sync");
                onError.accept(new Exception("Rate limit exceeded"));
                return;
            }
            recordRequest();
        }

        // Collect ranks on client thread
        clientThread.invoke(() -> {
            try {
                List<RankSyncRequest.RankUpdate> updates = collectRankUpdates();

                if (updates.isEmpty()) {
                    log.debug("No rank updates to sync");
                    return;
                }

                log.info("Collected {} rank updates, sending to backend", updates.size());

                // Send to backend via executor (off client thread)
                executor.submit(() -> sendRankUpdates(updates, onSuccess, onError));

            } catch (Exception e) {
                log.error("Error collecting rank updates", e);
                onError.accept(e);
            }
        });
    }

    /**
     * Collect rank updates from in-game clan roster.
     * MUST be called on client thread.
     * <p>
     * Uses ClanSettings.getMembers() to get ALL clan members (including offline),
     * not just online members from ClanChannel.
     */
    private List<RankSyncRequest.RankUpdate> collectRankUpdates() {
        List<RankSyncRequest.RankUpdate> updates = new ArrayList<>();

        ClanSettings clanSettings = client.getClanSettings();
        if (clanSettings == null) {
            log.debug("Clan settings not loaded - cannot collect ranks");
            return updates;
        }

        log.debug("[RankSync] Collecting ranks from clan: {}", clanSettings.getName());

        // Use ClanSettings.getMembers() to get ALL members (including offline)
        // This is what WOM does - it syncs the entire clan roster, not just online members
        List<net.runelite.api.clan.ClanMember> allMembers = clanSettings.getMembers();

        log.debug("[RankSync] Total clan members: {}", allMembers.size());

        // Track rank distribution for logging
        Map<String, Integer> rankCounts = new HashMap<>();

        for (net.runelite.api.clan.ClanMember member : allMembers) {
            String rsn = member.getName();

            // Skip bot accounts (names starting with [#)
            if (rsn.startsWith("[#")) {
                log.debug("[RankSync] Skipping bot account: {}", rsn);
                continue;
            }

            // Normalize RSN to Jagex format (spaces to underscores)
            // This matches WOM's approach and ensures consistent formatting
            String normalizedRsn = Text.toJagexName(rsn);

            ClanRank rank = member.getRank();
            int rankValue = rank.getRank();

            // Normalize rank to canonical backend value
            String canonicalRank = normalizeRank(rankValue, rank, clanSettings);

            if (canonicalRank != null) {
                updates.add(new RankSyncRequest.RankUpdate(normalizedRsn, canonicalRank));
                rankCounts.put(canonicalRank, rankCounts.getOrDefault(canonicalRank, 0) + 1);
            } else {
                log.debug("[RankSync] Skipping {} - unknown rank value {}", normalizedRsn, rankValue);
            }
        }

        // Log rank distribution at debug level only
        log.debug("[RankSync] Rank distribution: {}", rankCounts);

        return updates;
    }

    /**
     * Normalize a rank to canonical backend format using the clan title name.
     */
    private String normalizeRank(int rankValue, ClanRank rank, ClanSettings clanSettings) {
        ClanTitle title = clanSettings.titleForRank(rank);
        if (title != null && title.getName() != null && !title.getName().isEmpty()) {
            return title.getName().toLowerCase().replace("_", " ");
        }
        log.debug("[RankSync] No title found for rank value {}", rankValue);
        return null;
    }

    /**
     * Send rank updates to backend.
     * Handles batching if needed.
     */
    private void sendRankUpdates(List<RankSyncRequest.RankUpdate> updates,
                                 Consumer<RankSyncResponse> onSuccess,
                                 Consumer<Exception> onError) {

        // Batch if needed
        if (updates.size() > MAX_BATCH_SIZE) {
            int totalBatches = (updates.size() + MAX_BATCH_SIZE - 1) / MAX_BATCH_SIZE;
            log.info("Batching {} updates into {} chunks of {}", updates.size(), totalBatches, MAX_BATCH_SIZE);

            for (int i = 0; i < updates.size(); i += MAX_BATCH_SIZE) {
                int batchIndex = i / MAX_BATCH_SIZE;
                int end = Math.min(i + MAX_BATCH_SIZE, updates.size());
                List<RankSyncRequest.RankUpdate> batch = new ArrayList<>(updates.subList(i, end));

                // Schedule each batch with a staggered delay to avoid rate limiting
                // without blocking the shared executor thread
                executor.schedule(() -> {
                    log.info("Sending batch {}/{}", batchIndex + 1, totalBatches);
                    sendBatch(batch, onSuccess, onError);
                }, (long) batchIndex * 1000, TimeUnit.MILLISECONDS);
            }
        } else {
            sendBatch(updates, onSuccess, onError);
        }
    }

    /**
     * Send a single batch to backend.
     */
    private void sendBatch(List<RankSyncRequest.RankUpdate> updates,
                           Consumer<RankSyncResponse> onSuccess,
                           Consumer<Exception> onError) {

        RankSyncRequest request = new RankSyncRequest();
        request.setUpdates(updates);
        request.setCreateIfNotFound(true);

        String json = gson.toJson(request);
        RequestBody body = RequestBody.create(ApiConstants.JSON, json);

        Request httpRequest = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/members/ranks/sync")
                .post(body)
                .header("X-Member-Code", config.memberCode())
                .header("X-Account-Hash", String.valueOf(accountHash))
                .header("X-Auth-Token", authToken != null ? authToken : "")
                .header("Content-Type", "application/json")
                .header("User-Agent", ApiConstants.USER_AGENT)
                .build();

        httpClient.newCall(httpRequest).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Rank sync request failed", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        String errorBody = response.body() != null ? response.body().string() : "no body";
                        log.warn("Rank sync returned HTTP {}: {}", response.code(), errorBody);
                        onError.accept(new IOException("HTTP " + response.code()));
                        return;
                    }

                    assert response.body() != null;
                    String responseBody = response.body().string();
                    RankSyncResponse syncResponse = gson.fromJson(responseBody, RankSyncResponse.class);

                    // Single-line summary at INFO, details at debug
                    log.info("[RankSync] Done — synced:{} updated:{} unchanged:{} created:{}",
                            syncResponse.getSynced(), syncResponse.getUpdated(),
                            syncResponse.getUnchanged(), syncResponse.getCreated());
                    log.debug("[RankSync] Full response: {}", responseBody);

                    // Log not found members
                    if (syncResponse.getNotFound() != null && !syncResponse.getNotFound().isEmpty()) {
                        log.warn("[RankSync]   Not Found: {} members", syncResponse.getNotFound().size());
                        for (String rsn : syncResponse.getNotFound()) {
                            log.warn("[RankSync]     - {}", rsn);
                        }
                    }

                    // Log invalid entries
                    if (syncResponse.getInvalid() > 0) {
                        log.error("[RankSync]   Invalid: {} entries", syncResponse.getInvalid());
                    }

                    // Log detailed errors
                    if (syncResponse.getErrors() != null && !syncResponse.getErrors().isEmpty()) {
                        log.error("[RankSync] Errors:");
                        for (RankSyncResponse.SyncError error : syncResponse.getErrors()) {
                            String indexStr = error.getIndex() != null ? String.valueOf(error.getIndex()) : "?";

                            // Prefer rsnInput (raw input) over rsn (normalized)
                            String displayName = error.getRsnInput() != null ? error.getRsnInput() : error.getRsn();

                            if (displayName != null) {
                                log.error("[RankSync]   [{}] {} - {}", indexStr, displayName, error.getError());
                            } else {
                                log.error("[RankSync]   [{}] {}", indexStr, error.getError());
                            }
                        }
                    }

                    onSuccess.accept(syncResponse);

                } catch (Exception e) {
                    log.error("Error parsing rank sync response", e);
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * Check if we're within rate limits.
     */
    private boolean checkRateLimit() {
        long now = System.currentTimeMillis();

        // Remove old requests outside the window
        recentRequestTimes.removeIf(time -> now - time > RATE_LIMIT_WINDOW_MS);

        // Check if we can make another request
        return recentRequestTimes.size() < RATE_LIMIT_REQUESTS;
    }

    /**
     * Record a request for rate limiting.
     */
    private void recordRequest() {
        recentRequestTimes.add(System.currentTimeMillis());
    }
}

package com.boomerangbandits.services;

import com.boomerangbandits.api.models.PluginConfigResponse;
import com.boomerangbandits.api.ClanApiService;
import com.boomerangbandits.util.GameModeGuard;
import com.boomerangbandits.util.ScreenshotService;
import com.boomerangbandits.util.PopupNotificationService;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import com.google.common.collect.ImmutableSet;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.NpcSpawned;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import net.runelite.client.util.Text;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Color;
import java.util.Collection;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentLinkedQueue;

@Slf4j
@Singleton
public class BountyManager {
    private static final long WINDOW_MS = 10_000;
    private static final int NEARBY_TILE_DISTANCE = 5;
    private static final String FOLLOWED_MESSAGE = "You have a funny feeling like you're being followed";
    private static final String WOULD_HAVE_BEEN_FOLLOWED_MESSAGE = "You have a funny feeling like you would have been followed";

    // NPCs that fire LootReceived (with NPC type) but NOT NpcLootReceived.
    // Must be handled via LootReceived fallback.
    private static final Set<String> SPECIAL_LOOT_NPC_NAMES = ImmutableSet.of(
            "The Whisperer",
            "Araxxor",
            "Crystalline Hunllef",
            "Corrupted Hunllef",
            "Branda the Fire Queen",
            "Eldric the Ice King"
    );
    private final EventBus eventBus;
    private final ConfigSyncService configSyncService;
    private final ScreenshotService screenshotService;
    private final ChatMessageManager chatMessageManager;
    private final Client client;
    private final FeatureFlagService featureFlagService;
    private final ClanApiService clanApi;
    private final PopupNotificationService popupService;
    private final GameModeGuard gameModeGuard;
    private final ConcurrentLinkedQueue<NpcSpawnEntry> recentNpcSpawns = new ConcurrentLinkedQueue<>();

    @Inject
    public BountyManager(
            EventBus eventBus,
            ConfigSyncService configSyncService,
            ScreenshotService screenshotService,
            ChatMessageManager chatMessageManager,
            Client client,
            FeatureFlagService featureFlagService,
            ClanApiService clanApi,
            PopupNotificationService popupService,
            GameModeGuard gameModeGuard
    ) {
        this.eventBus = eventBus;
        this.configSyncService = configSyncService;
        this.screenshotService = screenshotService;
        this.chatMessageManager = chatMessageManager;
        this.client = client;
        this.featureFlagService = featureFlagService;
        this.clanApi = clanApi;
        this.popupService = popupService;
        this.gameModeGuard = gameModeGuard;
    }

    @Getter
	public static class NpcSpawnEntry {
        private final int npcId;
        private final long timestamp;

        public NpcSpawnEntry(int npcId, long timestamp) {
            this.npcId = npcId;
            this.timestamp = timestamp;
        }

	}

    @Subscribe
    public void onNpcSpawned(NpcSpawned event) {
        if (!gameModeGuard.isStandardWorld()) {
            return;
        }
        if (!featureFlagService.isBountyTrackingEnabled()) {
            return;
        }

        NPC npc = event.getNpc();
        Player localPlayer = client.getLocalPlayer();
        if (npc == null || localPlayer == null) {
            return;
        }

        WorldPoint npcLocation = npc.getWorldLocation();
        WorldPoint playerLocation = localPlayer.getWorldLocation();
        if (npcLocation == null || playerLocation == null) {
            return;
        }

        if (npcLocation.distanceTo(playerLocation) > NEARBY_TILE_DISTANCE) {
            return;
        }

        recentNpcSpawns.add(new NpcSpawnEntry(npc.getId(), System.currentTimeMillis()));
        pruneStaleSpawns();
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (!gameModeGuard.isStandardWorld()) {
            return;
        }
        if (!featureFlagService.isBountyTrackingEnabled() || event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        String message = Text.removeTags(event.getMessage());
        if (message == null ||
                (!message.contains(FOLLOWED_MESSAGE) && !message.contains(WOULD_HAVE_BEEN_FOLLOWED_MESSAGE))) {
            return;
        }

        pruneStaleSpawns();

        PluginConfigResponse latest = configSyncService.getLatestConfig();
        if (latest == null || latest.getBounties() == null || latest.getBounties().isEmpty()) {
            return;
        }

        for (PluginConfigResponse.Bounty bounty : latest.getBounties()) {
            if (bounty == null || bounty.getItems() == null) {
                continue;
            }

            for (PluginConfigResponse.BountyItem item : bounty.getItems()) {
                if (item == null || item.getNpcIds() == null || item.getNpcIds().isEmpty()) {
                    continue;
                }

                if (hasRecentSpawnMatch(item.getNpcIds())) {
                    onBountyCompleted(bounty, item);
                    return;
                }
            }
        }
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        if (!gameModeGuard.isStandardWorld()) {
            return;
        }
        checkLootForBounty(event.getItems());
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event) {
        if (!gameModeGuard.isStandardWorld()) {
            return;
        }
        checkLootForBounty(event.getItems());
    }

    /**
     * Fallback for special NPCs (Whisperer, Araxxor, Hunllef, etc.) that fire
     * LootReceived but NOT NpcLootReceived. Requires Loot Tracker plugin enabled.
     * Regular NPC loot is filtered out to avoid double-processing.
     */
    @Subscribe
    public void onLootReceived(LootReceived event) {
        if (!gameModeGuard.isStandardWorld()) {
            return;
        }
        if (event.getType() != LootRecordType.NPC || !SPECIAL_LOOT_NPC_NAMES.contains(event.getName())) {
            return;
        }
        checkLootForBounty(event.getItems());
    }

    private void checkLootForBounty(Collection<ItemStack> items) {
        if (!featureFlagService.isBountyTrackingEnabled() || items == null || items.isEmpty()) {
            return;
        }

        PluginConfigResponse latest = configSyncService.getLatestConfig();
        if (latest == null || latest.getBounties() == null || latest.getBounties().isEmpty()) {
            return;
        }

        for (PluginConfigResponse.Bounty bounty : latest.getBounties()) {
            if (bounty == null || bounty.getItems() == null) {
                continue;
            }

            for (PluginConfigResponse.BountyItem bountyItem : bounty.getItems()) {
                if (bountyItem == null || bountyItem.getItemId() <= 0) {
                    continue;
                }

                // Skip pet-mode items — those are handled via chat + NPC spawn correlation
                if (bountyItem.getNpcIds() != null && !bountyItem.getNpcIds().isEmpty()) {
                    continue;
                }

                if (hasLootItemMatch(items, bountyItem.getItemId())) {
                    onBountyCompleted(bounty, bountyItem);
                    return;
                }
            }
        }
    }

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        reset();
        eventBus.unregister(this);
    }

    public void reset() {
        recentNpcSpawns.clear();
    }


    private void pruneStaleSpawns() {
        long cutoff = System.currentTimeMillis() - WINDOW_MS;
        NpcSpawnEntry entry;
        while ((entry = recentNpcSpawns.peek()) != null && entry.getTimestamp() < cutoff) {
            recentNpcSpawns.poll();
        }
    }

    private boolean hasRecentSpawnMatch(List<Integer> npcIds) {
        for (NpcSpawnEntry spawnEntry : recentNpcSpawns) {
            if (npcIds.contains(spawnEntry.getNpcId())) {
                return true;
            }
        }
        return false;
    }

    private boolean hasLootItemMatch(Collection<ItemStack> items, int itemId) {
        return items.stream().anyMatch(itemStack -> itemStack.getId() == itemId);
    }

    private void onBountyCompleted(PluginConfigResponse.Bounty bounty, PluginConfigResponse.BountyItem item) {
        String bountyId = bounty.getId() != null ? bounty.getId() : "unknown";
        String bountyName = bounty.getName() != null && !bounty.getName().trim().isEmpty() ? bounty.getName() : bountyId;
        String itemName = item.getName() != null ? item.getName() : "Unknown Item";
        int itemId = item.getItemId();
        String rsn = client.getLocalPlayer() != null ? client.getLocalPlayer().getName() : "Unknown";

        screenshotService.captureScreenshot().thenAccept(base64 -> {
            log.info("Bounty completed: {} - {} (rsn={})", bountyId, itemName, rsn);

            // Show native OSRS popup (same as collection log notification)
            popupService.showPopup("Bounty Complete", "<col=FFFFFF>" + bountyName + "</col>:<br>" + itemName);

            chatMessageManager.queue(QueuedMessage.builder()
                    .type(ChatMessageType.BROADCAST)
                    .runeLiteFormattedMessage("<col=FFD700>[Boomerang Bandits]</col> Bounty completed: " + itemName)
                    .build());

            clanApi.submitBountyCompletion(bountyId, itemName, itemId, rsn, base64,
                    response -> {
                        if (response.isSuccess()) {
                            log.info("Bounty completion submitted to backend: {} - {}", bountyId, itemName);
                        } else {
                            log.warn("Backend rejected bounty completion: {} - {}: {}",
                                    bountyId, itemName, response.getMessage());
                        }
                    },
                    error -> log.warn("Failed to submit bounty completion: {} - {}: {}",
                            bountyId, itemName, error)
            );
        });
    }
}

package com.boomerangbandits.ui.components;

import com.boomerangbandits.ui.UIConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.MatteBorder;
import java.awt.*;

/**
 * Sticky footer bar pinned to the bottom of BoomerangPanel (outside the scroll area).
 * Contains a single Refresh button that calls the supplied action.
 * <p>
 * Loading state is reset automatically after a fixed timeout so it never gets stuck.
 */
public class PanelFooter extends JPanel {

    private static final int LOADING_TIMEOUT_MS = 5_000;

    private final JButton refreshBtn;
    private boolean loading = false;

    public PanelFooter(Runnable onRefresh) {
        setLayout(new GridBagLayout());
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(new MatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR));
        setPreferredSize(new Dimension(0, 28));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));

        refreshBtn = new JButton("Refresh");
        refreshBtn.setFont(FontManager.getRunescapeSmallFont());
        refreshBtn.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        refreshBtn.setBorder(null);
        refreshBtn.setContentAreaFilled(false);
        refreshBtn.setFocusPainted(false);
        refreshBtn.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        refreshBtn.addActionListener(e -> {
            if (!loading) {
                setLoading(true);
                onRefresh.run();
                // Safety timeout — re-enable after 5s in case the panel never calls back
                Timer timer = new Timer(LOADING_TIMEOUT_MS, ev -> resetLoading());
                timer.setRepeats(false);
                timer.start();
            }
        });

        GridBagConstraints c = new GridBagConstraints();
        c.gridx = 0;
        c.gridy = 0;
        c.weightx = 1.0;
        c.fill = GridBagConstraints.NONE;
        c.anchor = GridBagConstraints.CENTER;
        c.insets = new Insets(0, UIConstants.PADDING_SMALL, 0, UIConstants.PADDING_SMALL);
        add(refreshBtn, c);
    }

    public void setLoading(boolean loading) {
        this.loading = loading;
        SwingUtilities.invokeLater(() -> {
            refreshBtn.setText(loading ? "Loading..." : "Refresh");
            refreshBtn.setEnabled(!loading);
        });
    }

    public void resetLoading() {
        setLoading(false);
    }
}

package com.boomerangbandits.ui.components;

import javax.swing.*;
import java.awt.*;

/**
 * A JPanel that overrides getPreferredSize() to never report a width wider
 * than its parent's current width.
 *
 * <p>This breaks the bottom-up preferred-size propagation that causes horizontal
 * overflow in BoxLayout panels. Normally, BoxLayout asks each child for its
 * preferred width and uses the maximum as the panel's own preferred width —
 * which then propagates up to the scroll container and triggers a horizontal
 * scrollbar. By capping preferred width to the parent's actual width, we
 * ensure the scroll container never sees a width wider than the viewport.</p>
 *
 * <p>Use this as the content panel for CollapsibleSection and any other
 * BoxLayout container whose children might have wide preferred sizes.</p>
 */
public class WidthConstrainedPanel extends JPanel {

    public WidthConstrainedPanel(LayoutManager layout) {
        super(layout);
    }

    @Override
    public Dimension getPreferredSize() {
        Dimension pref = super.getPreferredSize();
        // If we have a parent, cap our preferred width to the parent's current width.
        // This prevents our children's unconstrained preferred widths from bubbling up.
        if (getParent() != null && getParent().getWidth() > 0) {
            return new Dimension(getParent().getWidth(), pref.height);
        }
        return pref;
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE);
    }
}

package com.boomerangbandits.ui.components;

import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;

/**
 * A label that counts down to a target time.
 * Updates every second via Swing Timer.
 * <p>
 * Usage:
 * CountdownLabel countdown = new CountdownLabel("Ends in: ");
 * countdown.setTarget("2025-06-15T12:00:00Z");
 * // Displays "Ends in: 3d 5h 12m"
 */
public class CountdownLabel extends JLabel {

    private final String prefix;
    private Instant targetTime;
    private Timer timer;

    public CountdownLabel(String prefix) {
        this.prefix = prefix;
        setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        setText(prefix + "--");
    }

    /**
     * Set the target time as ISO 8601 string.
     * Starts the countdown timer automatically.
     */
    public void setTarget(String iso8601) {
        try {
            this.targetTime = Instant.parse(iso8601);
            startTimer();
        } catch (DateTimeParseException e) {
            setText(prefix + "invalid");
        }
    }

    /**
     * Set the target time as Instant.
     */
    public void setTarget(Instant target) {
        this.targetTime = target;
        startTimer();
    }

    public void stop() {
        if (timer != null) {
            timer.stop();
            timer = null;
        }
    }

    private void startTimer() {
        stop(); // Stop existing timer
        updateDisplay();
        timer = new Timer(1000, e -> updateDisplay());
        timer.start();
    }

    private void updateDisplay() {
        if (targetTime == null) {
            setText(prefix + "--");
            return;
        }

        Duration remaining = Duration.between(Instant.now(), targetTime);
        if (remaining.isNegative()) {
            setText(prefix + "Ended");
            stop();
            return;
        }

        long days = remaining.toDays();
        long hours = remaining.toHours() % 24;
        long minutes = remaining.toMinutes() % 60;

        if (days > 0) {
            setText(prefix + days + "d " + hours + "h " + minutes + "m");
        } else if (hours > 0) {
            setText(prefix + hours + "h " + minutes + "m");
        } else {
            long seconds = remaining.getSeconds() % 60;
            setText(prefix + minutes + "m " + seconds + "s");
        }
    }
}

package com.boomerangbandits.ui.components;

import lombok.Getter;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Small icon button for the panel navigation bar.
 * Supports active/inactive states with visual feedback.
 * <p>
 * Usage:
 * NavButton btn = new NavButton(icon, "Home", () -> showPanel("HOME"));
 * navBar.add(btn);
 */
public class NavButton extends JButton {

    private static final int SIZE = 32;
    private static final Color ACTIVE_BG = ColorScheme.DARK_GRAY_COLOR;
    private static final Color INACTIVE_BG = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color HOVER_BG = ColorScheme.DARK_GRAY_HOVER_COLOR;
    private final Runnable onClick;
    @Getter
    private boolean active = false;

    public NavButton(ImageIcon icon, String tooltip, Runnable onClick) {
        this.onClick = onClick;

        setIcon(icon);
        setToolTipText(tooltip);
        setPreferredSize(new Dimension(SIZE, SIZE));
        setMinimumSize(new Dimension(SIZE, SIZE));
        setMaximumSize(new Dimension(SIZE, SIZE));
        setBorder(new EmptyBorder(4, 4, 4, 4));
        setContentAreaFilled(false);
        setFocusPainted(false);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setBackground(INACTIVE_BG);
        setOpaque(true);

        addActionListener(e -> onClick.run());
        addMouseAdapter();
    }

    public void setActive(boolean active) {
        this.active = active;
        setBackground(active ? ACTIVE_BG : INACTIVE_BG);
        repaint();
    }

    private void addMouseAdapter() {
        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                if (!active) setBackground(HOVER_BG);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                setBackground(active ? ACTIVE_BG : INACTIVE_BG);
            }
        });
    }
}

package com.boomerangbandits.ui.components;

import com.boomerangbandits.ui.components.AntialiasedLabel;

import com.boomerangbandits.ui.UIConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.AbstractTableModel;
import javax.swing.table.DefaultTableCellRenderer;
import java.awt.*;
import java.util.List;

/**
 * Reusable leaderboard table with rank, name, and value columns.
 * Styled to match RuneLite's dark theme.
 * <p>
 * Usage:
 * LeaderboardTable table = new LeaderboardTable("RSN", "Points");
 * table.setData(entries); // List<String[]> where each is {rank, name, value}
 */
public class LeaderboardTable extends JPanel {

    private final LeaderboardTableModel model;
    private final JTable table;
    private final JLabel emptyLabel;
    private final JScrollPane scrollPane;

    public LeaderboardTable(String nameHeader, String valueHeader) {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setAlignmentX(LEFT_ALIGNMENT);

        model = new LeaderboardTableModel(nameHeader, valueHeader);
        table = new JTable(model);
        table.setBackground(ColorScheme.DARK_GRAY_COLOR);
        table.setForeground(Color.WHITE);
        table.setGridColor(ColorScheme.MEDIUM_GRAY_COLOR);
        table.setRowHeight(UIConstants.ROW_HEIGHT_STANDARD);
        table.setShowGrid(false);
        table.setIntercellSpacing(new Dimension(0, 1));
        table.setFillsViewportHeight(true);
        table.getTableHeader().setBackground(ColorScheme.DARKER_GRAY_COLOR);
        table.getTableHeader().setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        table.getTableHeader().setFont(FontManager.getRunescapeBoldFont());

        // Column widths: rank=40, name=flex, value=60
        table.getColumnModel().getColumn(0).setMaxWidth(40);
        table.getColumnModel().getColumn(0).setMinWidth(30);
        table.getColumnModel().getColumn(2).setMaxWidth(80);
        table.getColumnModel().getColumn(2).setMinWidth(60);

        // Custom cell renderer for rank highlighting (top 3)
        table.getColumnModel().getColumn(0).setCellRenderer(new RankRenderer());

        scrollPane = new JScrollPane(table);
        scrollPane.setBorder(null);
        scrollPane.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scrollPane.setAlignmentX(LEFT_ALIGNMENT);
        // Width=0 means "take all available width" from the BoxLayout parent.
        // Height is set dynamically in setData() based on row count.
        scrollPane.setPreferredSize(new Dimension(0, 60));
        add(scrollPane);

        emptyLabel = new AntialiasedLabel("No data available");
        emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        emptyLabel.setHorizontalAlignment(JLabel.CENTER);
        emptyLabel.setBorder(new EmptyBorder(20, 0, 20, 0));
    }

    /**
     * Update the table data.
     *
     * @param rows list of String[3] arrays: {rank, name, value}
     */
    public void setData(List<String[]> rows) {
        model.setData(rows);
        removeAll();
        if (rows == null || rows.isEmpty()) {
            emptyLabel.setAlignmentX(LEFT_ALIGNMENT);
            add(emptyLabel);
        } else {
            // Resize scroll pane height to fit all rows — outer scrollWrap handles page scroll
            int headerHeight = table.getTableHeader().getPreferredSize().height;
            int height = headerHeight + (model.getRowCount() * table.getRowHeight()) + 4;
            scrollPane.setPreferredSize(new Dimension(0, Math.max(height, 60)));
            add(scrollPane);
        }
        revalidate();
        repaint();
    }

    // Table model
    private static class LeaderboardTableModel extends AbstractTableModel {
        private final String[] headers;
        private List<String[]> data = List.of();

        LeaderboardTableModel(String nameHeader, String valueHeader) {
            this.headers = new String[]{"#", nameHeader, valueHeader};
        }

        void setData(List<String[]> data) {
            this.data = data != null ? data : List.of();
            fireTableDataChanged();
        }

        @Override
        public int getRowCount() {
            return data.size();
        }

        @Override
        public int getColumnCount() {
            return 3;
        }

        @Override
        public String getColumnName(int col) {
            return headers[col];
        }

        @Override
        public Object getValueAt(int row, int col) {
            return row < data.size() && col < data.get(row).length ? data.get(row)[col] : "";
        }
    }

    // Rank cell renderer — highlights top 3
    private static class RankRenderer extends DefaultTableCellRenderer {
        private static final Color GOLD = new Color(0xFFD700);
        private static final Color SILVER = new Color(0xC0C0C0);
        private static final Color BRONZE = new Color(0xCD7F32);

        @Override
        public Component getTableCellRendererComponent(JTable t, Object val,
                                                       boolean sel, boolean focus, int row, int col) {
            super.getTableCellRendererComponent(t, val, sel, focus, row, col);
            setHorizontalAlignment(CENTER);
            setBackground(ColorScheme.DARK_GRAY_COLOR);
            switch (row) {
                case 0:
                    setForeground(GOLD);
                    break;
                case 1:
                    setForeground(SILVER);
                    break;
                case 2:
                    setForeground(BRONZE);
                    break;
                default:
                    setForeground(Color.WHITE);
            }
            return this;
        }
    }
}

package com.boomerangbandits.ui.components;


import javax.swing.*;
import java.awt.*;

/**
 * Small coloured badge for displaying rank, status, or category labels.
 * <p>
 * Usage:
 * Badge = new Badge("Admin", new Color(0x4CAF50));
 * panel.add(badge);
 */
public class Badge extends JComponent {

    private static final int PAD_X = 4;
    private static final int PAD_Y = 2;
    private static final int ARC = 10;
    private final Color textColor;
    private String text;
    private Color bgColor;

    public Badge(String text, Color bgColor) {
        this(text, bgColor, Color.WHITE);
    }

    public Badge(String text, Color bgColor, Color textColor) {
        this.text = text;
        this.bgColor = bgColor;
        this.textColor = textColor;
        setOpaque(false);
    }

    public void setText(String text) {
        this.text = text;
        revalidate();
        repaint();
    }

    public void setBgColor(Color bgColor) {
        this.bgColor = bgColor;
        repaint();
    }

    @Override
    public Dimension getPreferredSize() {
        FontMetrics fm = getFontMetrics(getFont());
        int width = fm.stringWidth(text) + PAD_X * 2;
        int height = fm.getHeight() + PAD_Y * 2;
        return new Dimension(width, height);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // Background
        g2.setColor(bgColor);
        g2.fillRoundRect(0, 0, getWidth(), getHeight(), ARC, ARC);

        // Text
        g2.setFont(getFont());
        g2.setColor(textColor);
        FontMetrics fm = g2.getFontMetrics();
        int x = (getWidth() - fm.stringWidth(text)) / 2;
        int y = (getHeight() + fm.getAscent() - fm.getDescent()) / 2;
        g2.drawString(text, x, y);

        g2.dispose();
    }
}

package com.boomerangbandits.ui.components;

import com.boomerangbandits.ui.UIConstants;
import lombok.Getter;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * A collapsible panel section with a clickable header.
 * <p>
 * Uses BoxLayout Y_AXIS so width is always driven by the parent container,
 * never by the content's unconstrained preferred width. This prevents
 * horizontal overflow when placed inside a scrollWrap() panel.
 */
public class CollapsibleSection extends JPanel {
    private final JPanel contentPanel;
    private final JLabel arrowLabel;
    private final JPanel headerPanel;
    @Getter
    private boolean expanded;

    public CollapsibleSection(String title, JPanel content, boolean startExpanded) {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(0, 0, UIConstants.SPACING_ITEM, 0));
        setAlignmentX(LEFT_ALIGNMENT);

        this.expanded = startExpanded;
        this.contentPanel = content;
        contentPanel.setVisible(expanded);
        // Content must also not push width — cap it
        contentPanel.setAlignmentX(LEFT_ALIGNMENT);
        contentPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        // Header row: arrow on left, title fills rest
        headerPanel = new JPanel(new BorderLayout(UIConstants.SPACING_SMALL, 0));
        headerPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        headerPanel.setBorder(new EmptyBorder(
                UIConstants.SPACING_SMALL,
                UIConstants.PADDING_STANDARD,
                UIConstants.SPACING_SMALL,
                UIConstants.PADDING_STANDARD
        ));
        headerPanel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        headerPanel.setAlignmentX(LEFT_ALIGNMENT);
        headerPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        arrowLabel = new AntialiasedLabel(expanded ? "v" : ">");
        arrowLabel.setFont(FontManager.getRunescapeSmallFont());
        arrowLabel.setForeground(ColorScheme.BRAND_ORANGE);

        JLabel titleLabel = new AntialiasedLabel(title);
        titleLabel.setFont(FontManager.getRunescapeBoldFont());
        titleLabel.setForeground(Color.WHITE);

        headerPanel.add(arrowLabel, BorderLayout.WEST);
        headerPanel.add(titleLabel, BorderLayout.CENTER);

        headerPanel.addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e)) {
                    setExpanded(!expanded);
                }
            }

            @Override
            public void mouseEntered(MouseEvent e) {
                headerPanel.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                headerPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            }
        });

        add(headerPanel);
        add(contentPanel);
    }

    public void setExpanded(boolean expanded) {
        this.expanded = expanded;
        arrowLabel.setText(expanded ? "v" : ">");
        contentPanel.setVisible(expanded);
        revalidate();
        repaint();
    }

    @Override
    public Dimension getPreferredSize() {
        Dimension pref = super.getPreferredSize();
        if (getParent() != null && getParent().getWidth() > 0) {
            return new Dimension(getParent().getWidth(), pref.height);
        }
        return pref;
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE);
    }
}

