            if (code.isEmpty()) {
                statusLabel.setForeground(new Color(0xFF6B6B));
                statusLabel.setText("Enter a member code");
                statusLabel.setVisible(true);
                return;
            }
            configManager.setConfiguration(BoomerangBanditsConfig.GROUP, "memberCode", code);
            statusLabel.setForeground(new Color(0x4CAF50));
            statusLabel.setText("Saved!");
            statusLabel.setVisible(true);
        };

        saveButton.addActionListener(e -> saveMemberCode.run());
        memberCodeField.addActionListener(e -> saveMemberCode.run());

        memberCodeInputSection.add(saveButton);
        memberCodeInputSection.add(Box.createVerticalStrut(6));
        memberCodeInputSection.add(statusLabel);

        panel.add(memberCodeInputSection);

        panel.add(Box.createVerticalGlue());

        return panel;
    }

    /**
     * Wraps a panel in a vertical-only scroll pane that fills available width.
     */
    private JScrollPane scrollWrap(JPanel panel) {
        // If the panel implements Scrollable with getScrollableTracksViewportWidth()=true,
        // put it directly as the viewport view — the Scrollable contract handles width.
        // Otherwise use the northWrapper pattern to pin content to top.
        final JComponent viewportView;
        if (panel instanceof Scrollable && ((Scrollable) panel).getScrollableTracksViewportWidth()) {
            viewportView = panel;
        } else {
            JPanel northWrapper = new JPanel(new BorderLayout());
            northWrapper.setBackground(ColorScheme.DARK_GRAY_COLOR);
            northWrapper.add(panel, BorderLayout.NORTH);
            viewportView = northWrapper;
        }

        JScrollPane scroll = new JScrollPane(viewportView,
                ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
                ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setBorder(null);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        return scroll;
    }

    /**
     * Show a specific sub-panel by card name.
     * Updates nav button active states.
     * Triggers lazy initialization and refresh on the target panel.
     */
    public void showCard(String card) {
        this.activeCard = card;

        cardLayout.show(contentPanel, card);

        // Update nav button active states
        String[] cards = {CARD_HOME, CARD_LEADERBOARD, CARD_COMPETITION, CARD_HUB};
        for (int i = 0; i < navButtons.size() && i < cards.length; i++) {
            navButtons.get(i).setActive(cards[i].equals(card));
        }

        // Admin button highlight
        if (adminButton != null) {
            adminButton.setOpaque(CARD_ADMIN.equals(card));
            adminButton.setBackground(CARD_ADMIN.equals(card)
                    ? ColorScheme.DARK_GRAY_COLOR : ColorScheme.DARKER_GRAY_COLOR);
        }

        // Refresh the target panel's data
        refreshPanel(card);
    }

    /**
     * Force-refresh the currently visible panel, bypassing all throttle cooldowns.
     * Called by the refresh button in the nav bar.
     */
    public void forceRefreshActivePanel() {
        switch (activeCard) {
            case CARD_HOME:
                homePanel.forceRefreshAll();
                break;
            case CARD_LEADERBOARD:
                leaderboardPanel.forceRefresh();
                break;
            case CARD_COMPETITION:
                competitionPanel.forceRefresh();
                break;
            case CARD_HUB:
                hubPanel.refresh();
                break;
        }
    }

    /**
     * Refresh a specific panel's data.
     */
    private void refreshPanel(String card) {
        log.debug("[BoomerangPanel] refreshPanel() called for card: {}", card);
        switch (card) {
            case CARD_HOME:
                log.debug("[BoomerangPanel] Refreshing HOME panel data");
                homePanel.refresh();
                log.debug("[BoomerangPanel] HOME panel refresh complete");
                break;
            case CARD_LEADERBOARD:
                leaderboardPanel.refresh();
                break;
            case CARD_COMPETITION:
                competitionPanel.refresh();
                break;
            case CARD_HUB:
                hubPanel.refresh();
                break;
            case CARD_ADMIN:
                break;
        }
    }

    // Legacy methods for Phase 1 compatibility
    public void onLogin(String rsn) {
        homePanel.updateGreeting(rsn);
        homePanel.updateStatus("Authenticating...", ColorScheme.LIGHT_GRAY_COLOR);
    }

    public void onAuthenticated() {
        showUnlocked();
        homePanel.updateStatus("Connected", new Color(0x4CAF50));
    }

    public void onDegraded() {
        homePanel.updateStatus("Degraded mode", new Color(0xFFC107));
    }

    public void onLogout() {
        showLocked();
        homePanel.updateGreeting("Adventurer");
        homePanel.updateStatus("Not connected", ColorScheme.LIGHT_GRAY_COLOR);
    }

    /**
     * Show the locked screen — hides nav bar, footer, and all content panels.
     */
    public void showLocked() {
        cardLayout.show(contentPanel, CARD_LOCKED);
        activeCard = CARD_LOCKED;
        if (navBar != null) navBar.setVisible(false);
        if (stickyFooter != null) stickyFooter.setVisible(false);
        if (memberCodeInputSection != null) memberCodeInputSection.setVisible(false);
    }

    /**
     * Unlock the panel — show nav bar, footer, and navigate to home.
     */
    public void showUnlocked() {
        if (navBar != null) navBar.setVisible(true);
        if (stickyFooter != null) stickyFooter.setVisible(true);
        showCard(CARD_HOME);
    }

    public void refreshConfig() {
        if (CARD_LOCKED.equals(activeCard)) {
            log.debug("[BoomerangPanel] refreshConfig() skipped — panel locked");
            return;
        }
        log.debug("[BoomerangPanel] refreshConfig() called");
        homePanel.forceRefreshAll();
    }

    /**
     * Update admin button visibility based on player's clan rank.
     * Reads ClanSettings on the client thread, then updates UI on the EDT.
     */
    public void updateAdminVisibility() {
        clientThread.invoke(() -> {
            boolean isAdmin = clanValidator.isAdmin();
            SwingUtilities.invokeLater(() -> adminButton.setVisible(isAdmin));
        });
    }

    /**
     * Show the member code input on the locked screen.
     * Call after clan validation passes but before authentication completes,
     * so the player can enter their code without going to config.
     */
    public void showMemberCodeInput() {
        if (memberCodeInputSection != null) {
            memberCodeInputSection.setVisible(true);
            memberCodeInputSection.revalidate();
            memberCodeInputSection.repaint();
        }
    }
}

package com.boomerangbandits.ui;

import java.awt.*;
import javax.swing.*;

/**
 * Centralized UI constants for consistent styling across all panels.
 * <p>
 * Modify these values to adjust the look and feel of the entire plugin.
 */
public class UIConstants {

    // ======================================================================
    // FONT SIZES
    // ======================================================================

    /**
     * Large heading text (e.g., panel titles, main headers)
     */
    public static final float FONT_SIZE_LARGE = 14f;

    /**
     * Medium heading text (e.g., section headers)
     */
    public static final float FONT_SIZE_MEDIUM = 12f;

    /**
     * Normal body text (e.g., labels, descriptions)
     */
    public static final float FONT_SIZE_NORMAL = 11f;

    /**
     * Small text (e.g., secondary info, timestamps)
     */
    public static final float FONT_SIZE_SMALL = 10f;

    /**
     * Extra large display text (e.g., points totals, big numbers)
     */
    public static final float FONT_SIZE_DISPLAY = 24f;

    // ======================================================================
    // FONT STYLES
    // ======================================================================

    public static final int FONT_BOLD = Font.BOLD;
    public static final int FONT_PLAIN = Font.PLAIN;
    public static final int FONT_ITALIC = Font.ITALIC;

    // ======================================================================
    // SPACING
    // ======================================================================

    /**
     * Standard padding inside components
     */
    public static final int PADDING_STANDARD = 8;

    /**
     * Large padding for major sections
     */
    public static final int PADDING_LARGE = 12;

    /**
     * Small padding for compact layouts
     */
    public static final int PADDING_SMALL = 4;

    /**
     * Vertical spacing between sections
     */
    public static final int SPACING_SECTION = 16;

    /**
     * Vertical spacing between items
     */
    public static final int SPACING_ITEM = 8;

    /**
     * Small vertical spacing
     */
    public static final int SPACING_SMALL = 4;

    // ======================================================================
    // COMPONENT HEIGHTS
    // ======================================================================

    /**
     * Standard row height for list items
     */
    public static final int ROW_HEIGHT_STANDARD = 24;

    /**
     * Compact row height
     */
    public static final int ROW_HEIGHT_COMPACT = 20;

    /**
     * Large row height for prominent items
     */
    public static final int ROW_HEIGHT_LARGE = 30;

    /**
     * Points display box height
     */
    public static final int POINTS_DISPLAY_HEIGHT = 80;

    // ======================================================================
    // HELPER METHODS
    // ======================================================================

    private UIConstants() {
        // Utility class, no instantiation
    }

    /**
     * Create a font with the specified size and style.
     *
     * @param baseFont the base font to derive from
     * @param size     one of the FONT_SIZE_* constants
     * @param style    one of the FONT_* style constants
     * @return derived font
     */
    public static Font deriveFont(Font baseFont, float size, int style) {
        return baseFont.deriveFont(style, size);
    }

    /**
     * Create a font with the specified size (plain style).
     *
     * @param baseFont the base font to derive from
     * @param size     one of the FONT_SIZE_* constants
     * @return derived font
     */
    public static Font deriveFont(Font baseFont, float size) {
        return baseFont.deriveFont(size);
    }

    /**
     * Apply high-quality text rendering hints to a Graphics2D context.
     * This improves text clarity on lower resolution displays (1440p and below).
     *
     * @param g2d the Graphics2D context to configure
     */
    public static void applyTextRenderingHints(Graphics2D g2d) {
        g2d.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g2d.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2d.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
    }

    /**
     * Capitalize the first letter of a string, preserving the rest.
     *
     * @param str the string to capitalize
     * @return the capitalized string, or the original if null/empty
     */
    public static String capitalize(String str) {
        if (str == null || str.isEmpty()) return str;
        return str.substring(0, 1).toUpperCase() + str.substring(1);
    }

    /**
     * Capitalize the first letter and lowercase the rest.
     *
     * @param str the string to capitalize
     * @return the capitalized string, or the original if null/empty
     */
    public static String capitalizeLower(String str) {
        if (str == null || str.isEmpty()) return str;
        return str.substring(0, 1).toUpperCase() + str.substring(1).toLowerCase();
    }

    /**
     * Create a left-right key-value row using GridBagLayout.
     * Left label stretches to fill, right label anchors to the east.
     * Callers can further customize the returned panel (maxSize, border, etc).
     */
    public static JPanel createKeyValueRow(JLabel left, JLabel right, Color background) {
        JPanel row = new JPanel(new GridBagLayout());
        row.setBackground(background);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        GridBagConstraints c = new GridBagConstraints();
        c.gridy = 0;

        c.gridx = 0;
        c.weightx = 1.0;
        c.fill = GridBagConstraints.HORIZONTAL;
        c.anchor = GridBagConstraints.WEST;
        c.insets = new Insets(0, 0, 0, 4);
        row.add(left, c);

        c.gridx = 1;
        c.weightx = 0.0;
        c.fill = GridBagConstraints.NONE;
        c.anchor = GridBagConstraints.EAST;
        c.insets = new Insets(0, 0, 0, 0);
        row.add(right, c);

        return row;
    }
}

package com.boomerangbandits.ui.panels;

import com.boomerangbandits.api.ClanApiService;
import com.boomerangbandits.api.models.LeaderboardEntry;
import com.boomerangbandits.ui.UIConstants;
import com.boomerangbandits.ui.components.AntialiasedLabel;
import com.boomerangbandits.ui.components.LeaderboardTable;
import com.boomerangbandits.util.RefreshThrottler;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Clan leaderboard panel showing points-based rankings.
 * <p>
 * Data source: Backend GET /api/leaderboard (paginated)
 * Uses LeaderboardTable reusable component.
 */
public class LeaderboardPanel extends JPanel {

    private static final int PER_PAGE = 50;

    private final ClanApiService clanApi;
    private final LeaderboardTable table;
    private final RefreshThrottler refreshThrottler;

    private final JLabel pageLabel;
    private final JButton prevButton;
    private final JButton nextButton;
    private int currentPage = 1;
    private int totalPages = 1;

    @Inject
    public LeaderboardPanel(ClanApiService clanApi) {
        this.clanApi = clanApi;
        this.refreshThrottler = new RefreshThrottler(60 * 60 * 1_000); // 1 hour

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // Header
        JLabel header = new AntialiasedLabel("Clan Leaderboard");
        header.setForeground(java.awt.Color.WHITE);
        header.setFont(FontManager.getRunescapeBoldFont());
        header.setBorder(new EmptyBorder(
                UIConstants.PADDING_STANDARD,
                UIConstants.PADDING_STANDARD,
                UIConstants.PADDING_STANDARD,
                UIConstants.PADDING_STANDARD
        ));
        header.setAlignmentX(LEFT_ALIGNMENT);
        add(header);

        // Table
        table = new LeaderboardTable("Player", "Points");
        table.setAlignmentX(LEFT_ALIGNMENT);
        add(table);

        // Pagination
        JPanel pagination = new JPanel(new FlowLayout(FlowLayout.CENTER, UIConstants.SPACING_ITEM, UIConstants.SPACING_SMALL));
        pagination.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        pagination.setAlignmentX(LEFT_ALIGNMENT);

        prevButton = new JButton("<");
        prevButton.setEnabled(false);
        prevButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        prevButton.addActionListener(e -> loadPage(currentPage - 1));
        pagination.add(prevButton);

        pageLabel = new AntialiasedLabel("1 / 1");
        pageLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        pagination.add(pageLabel);

        nextButton = new JButton(">");
        nextButton.setEnabled(false);
        nextButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        nextButton.addActionListener(e -> loadPage(currentPage + 1));
        pagination.add(nextButton);

        add(pagination);
    }

    /**
     * Load and display a specific page.
     * Safe to call from any thread.
     */
    public void loadPage(int page) {
        clanApi.fetchLeaderboard(page, PER_PAGE,
                response -> SwingUtilities.invokeLater(() -> {
                    currentPage = response.getPage();
                    totalPages = response.getPages();

                    List<String[]> rows = new ArrayList<>();
                    for (LeaderboardEntry entry : response.getLeaderboard()) {
                        rows.add(new String[]{
                                String.valueOf(entry.getRank()),
                                entry.getRsn(),
                                String.format("%,d", entry.getTotalPoints())
                        });
                    }
                    table.setData(rows);

                    pageLabel.setText(currentPage + " / " + totalPages);
                    prevButton.setEnabled(currentPage > 1);
                    nextButton.setEnabled(currentPage < totalPages);
                }),
                error -> SwingUtilities.invokeLater(() ->
                        table.setData(null)
                )
        );
    }

    /**
     * Refresh the current page.
     * Throttled to prevent excessive API calls (30s cooldown).
     */
    public void refresh() {
        if (!refreshThrottler.shouldRefresh()) {
            return; // Data is fresh enough
        }
        refreshThrottler.recordRefresh();
        loadPage(currentPage);
    }

    /**
     * Force refresh (bypasses cooldown).
     */
    public void forceRefresh() {
        refreshThrottler.reset();
        refresh();
    }
}

package com.boomerangbandits.ui.panels;

import com.boomerangbandits.api.AdminApiService;
import com.boomerangbandits.api.models.AttendanceEntry;
import com.boomerangbandits.api.models.RankChange;
import com.boomerangbandits.services.EventAttendanceTracker;
import com.boomerangbandits.ui.components.AntialiasedLabel;
import com.boomerangbandits.ui.components.AntialiasedTextArea;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.List;

/**
 * Admin panel — attendance ingestion, rank changes, announcements, roster sync.
 * <p>
 * Layout rules:
 * - Top-level panel uses BoxLayout (Rule 2) — no internal JScrollPane (Rule 1)
 * - Every direct BoxLayout child has setMaximumSize + setAlignmentX(LEFT_ALIGNMENT) (Rule 4)
 * - Labels inside BoxLayout are wrapped in a GridBagLayout row panel (Rule 10)
 * - No FlowLayout for rows — use a fixed-height JPanel with GridBagLayout (Rule 5)
 */
@Slf4j
public class AdminPanel extends JPanel implements Scrollable {

    private final AdminApiService adminApi;
    @Setter
    private Runnable onGroupSync;
    private EventAttendanceTracker attendanceTracker;

    // Attendance section
    private JTextField eventNameField;
    private JSpinner thresholdSpinner;
    private JButton startEventButton;
    private JButton stopSubmitButton;
    private JLabel attendanceStatusLabel;
    private JLabel attendanceResultLabel;

    // Rank changes section
    private JPanel rankChangesContainer;
    private JButton refreshRankChangesButton;

    // Announcement section
    private AntialiasedTextArea announcementTextArea;
    private JButton updateAnnouncementButton;
    private JLabel announcementResultLabel;

    // Roster sync section
    private JButton syncRosterButton;
    private JLabel syncRosterResultLabel;

    @Inject
    public AdminPanel(AdminApiService adminApi) {
        this(adminApi, null);
    }

    public AdminPanel(AdminApiService adminApi, Runnable onGroupSync) {
        this.adminApi = adminApi;
        this.onGroupSync = onGroupSync;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(8, 8, 8, 8));

        JLabel title = new AntialiasedLabel("Admin Panel");
        title.setForeground(Color.WHITE);
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setAlignmentX(LEFT_ALIGNMENT);
        title.setBorder(new EmptyBorder(0, 0, 8, 0));
        add(title);

        add(buildAttendanceSection());
        add(javax.swing.Box.createVerticalStrut(8));
        add(buildRankChangesSection());
        add(javax.swing.Box.createVerticalStrut(8));
        add(buildAnnouncementSection());
        add(javax.swing.Box.createVerticalStrut(8));
        add(buildRosterSyncSection());
    }

    // =========================================================================
    // Section 1: Attendance Tracking
    // =========================================================================

    private JPanel buildAttendanceSection() {
        JPanel section = createSection("Event Attendance");

        addLabelRow(section,
                "<html>Start tracking when the event begins. Stop & Submit when done — "
                        + "attendance is sent directly to the backend.</html>", 10f);

        section.add(javax.swing.Box.createVerticalStrut(6));

        // Event name row
        JPanel nameRow = new JPanel(new GridBagLayout());
        nameRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        nameRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        nameRow.setAlignmentX(LEFT_ALIGNMENT);

        GridBagConstraints c = new GridBagConstraints();
        c.gridy = 0;
        c.insets = new Insets(0, 0, 0, 4);

        JLabel nameLabel = new AntialiasedLabel("Event name:");
        nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        c.gridx = 0;
        c.weightx = 0;
        c.fill = GridBagConstraints.NONE;
        c.anchor = GridBagConstraints.WEST;
        nameRow.add(nameLabel, c);

        eventNameField = new JTextField();
        eventNameField.setBackground(ColorScheme.DARK_GRAY_COLOR);
        eventNameField.setForeground(Color.WHITE);
        eventNameField.setCaretColor(Color.WHITE);
        eventNameField.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
                new EmptyBorder(2, 4, 2, 4)
        ));
        c.gridx = 1;
        c.weightx = 1.0;
        c.fill = GridBagConstraints.HORIZONTAL;
        c.insets = new Insets(0, 0, 0, 0);
        nameRow.add(eventNameField, c);

        section.add(nameRow);
        section.add(javax.swing.Box.createVerticalStrut(4));

        // Threshold row — "Min. time (min): [spinner]"
        JPanel thresholdRow = new JPanel(new GridBagLayout());
        thresholdRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        thresholdRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 26));
        thresholdRow.setAlignmentX(LEFT_ALIGNMENT);

        GridBagConstraints tc = new GridBagConstraints();
        tc.gridy = 0;
        tc.insets = new Insets(0, 0, 0, 4);

        JLabel thresholdLabel = new AntialiasedLabel("Min. time (min):");
        thresholdLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        thresholdLabel.setFont(FontManager.getRunescapeSmallFont());
        tc.gridx = 0;
        tc.weightx = 1.0;
        tc.fill = GridBagConstraints.HORIZONTAL;
        tc.anchor = GridBagConstraints.WEST;
        thresholdRow.add(thresholdLabel, tc);

        // default 10 min, range 1–120
        thresholdSpinner = new JSpinner(new SpinnerNumberModel(10, 1, 120, 1));
        thresholdSpinner.setPreferredSize(new Dimension(52, 22));
        tc.gridx = 1;
        tc.weightx = 0;
        tc.fill = GridBagConstraints.NONE;
        tc.insets = new Insets(0, 0, 0, 0);
        thresholdRow.add(thresholdSpinner, tc);

        section.add(thresholdRow);
        section.add(javax.swing.Box.createVerticalStrut(6));

        // Live status label
        attendanceStatusLabel = new AntialiasedLabel("No event running");
        attendanceStatusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        attendanceStatusLabel.setFont(FontManager.getRunescapeSmallFont());
        addLabelComponent(section, attendanceStatusLabel);

        section.add(javax.swing.Box.createVerticalStrut(4));

        // Start button
        startEventButton = makeButton("Start Event");
        startEventButton.addActionListener(e -> startAttendanceEvent());
        section.add(startEventButton);

        section.add(javax.swing.Box.createVerticalStrut(4));

        // Stop & Submit button — disabled until event is running
        stopSubmitButton = makeButton("Stop & Submit");
        stopSubmitButton.setEnabled(false);
        stopSubmitButton.addActionListener(e -> stopAndSubmitAttendance());
        section.add(stopSubmitButton);

        section.add(javax.swing.Box.createVerticalStrut(2));

        attendanceResultLabel = new AntialiasedLabel(" ");
        attendanceResultLabel.setFont(FontManager.getRunescapeSmallFont());
        addLabelComponent(section, attendanceResultLabel);

        return section;
    }

    private void startAttendanceEvent() {
        if (attendanceTracker == null) return;
        attendanceTracker.startEvent();
        startEventButton.setEnabled(false);
        stopSubmitButton.setEnabled(true);
        attendanceStatusLabel.setText("Event running — tracking members...");
        attendanceStatusLabel.setForeground(new Color(0x4CAF50));
        attendanceResultLabel.setText(" ");

        // Tick a live counter every second
        Timer liveTimer = new Timer(1000, null);
        liveTimer.addActionListener(e -> {
            if (attendanceTracker == null || !attendanceTracker.isRunning()) {
                liveTimer.stop();
                return;
            }
            int secs = attendanceTracker.getEventDurationSeconds();
            int mins = secs / 60;
            attendanceStatusLabel.setText(String.format(
                    "Running %02d:%02d — %d members seen",
                    mins, secs % 60, attendanceTracker.getMemberCount()
            ));
        });
        liveTimer.start();
    }

    private void stopAndSubmitAttendance() {
        if (attendanceTracker == null || adminApi == null) return;

        String eventName = eventNameField.getText().trim();
        int thresholdSeconds = (int) thresholdSpinner.getValue() * 60;
        java.util.List<AttendanceEntry> entries = attendanceTracker.stopEvent(thresholdSeconds, thresholdSeconds / 2);
        int duration = attendanceTracker.getEventDurationSeconds();

        startEventButton.setEnabled(true);
        stopSubmitButton.setEnabled(false);
        attendanceStatusLabel.setText("Submitting " + entries.size() + " entries...");
        attendanceStatusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

        adminApi.submitAttendance(
                eventName.isEmpty() ? "Unnamed Event" : eventName,
                duration,
                entries,
                result -> SwingUtilities.invokeLater(() -> {
                    if (result.isSuccess()) {
                        attendanceStatusLabel.setText("Done — event ended");
                        attendanceStatusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
                        attendanceResultLabel.setText(String.format(
                                "Submitted %d, matched %d, %d pts each",
                                result.getTotalSubmitted(), result.getMatched(), result.getPointsAwarded()
                        ));
                        attendanceResultLabel.setForeground(new Color(0x4CAF50));
                        if (result.getUnmatched() != null && !result.getUnmatched().isEmpty()) {
                            JOptionPane.showMessageDialog(this,
                                    "Unmatched RSNs (not in backend):\n\n"
                                            + String.join("\n", result.getUnmatched()),
                                    "Unmatched Players", JOptionPane.INFORMATION_MESSAGE);
                        }
                        eventNameField.setText("");
                    } else {
                        attendanceResultLabel.setText("Submission failed");
                        attendanceResultLabel.setForeground(new Color(0xFF5252));
                    }
                }),
                error -> SwingUtilities.invokeLater(() -> {
                    attendanceResultLabel.setText(error instanceof SecurityException
                            ? "Access denied" : "Error: " + error.getMessage());
                    attendanceResultLabel.setForeground(new Color(0xFF5252));
                })
        );
    }

