        JLabel label = new AntialiasedLabel(placeholder);
        label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
        label.setAlignmentX(LEFT_ALIGNMENT);
        parent.add(label);
        parent.add(field);
        parent.add(javax.swing.Box.createVerticalStrut(UIConstants.SPACING_SMALL));
