        name = "Boomerang Bandits",
        description = "Official plugin for Boomerang Bandits clan members",
        tags = {"clan", "boomerang", "bandits", "events", "tracking", "cc"}
)
@Slf4j
public class BoomerangBanditsPlugin extends Plugin {

    // RuneLite injected dependencies
    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private ConfigManager configManager;
    @Inject
    private ClientToolbar clientToolbar;
    @Inject
    private EventBus eventBus;
    @Inject
    private ScheduledExecutorService executor;
    @Inject
    private OverlayManager overlayManager;

    // Plugin components
    @Inject
    private BoomerangBanditsConfig config;
    @Inject
    private AuthHeaderInterceptor authInterceptor;
    @Inject
    private ClanApiService clanApi;
    @Inject
    private ClanContentService contentService;
    @Inject
    private AdminApiService adminApi;
    @Inject
    private ClanValidator clanValidator;
    @Inject
    private ConfigSyncService configSyncService;

    // Phase 2: Services
    @Inject
    private WomApiService womApi;
    @Inject
    private CompetitionScheduler competitionScheduler;

    // Clan Rank Sync
    @Inject
    private com.boomerangbandits.services.ClanRankSyncService clanRankSyncService;

    // Attendance tracking
    @Inject
    private EventAttendanceTracker attendanceTracker;

    // Sound effects
    @Inject
    private com.boomerangbandits.services.CofferDepositSoundService cofferDepositSoundService;
    @Inject
    private InGameAnnouncementService inGameAnnouncementService;
    @Inject
    private ItemRenameManager itemRenameManager;
    @Inject
    private NPCRenameManager npcRenameManager;
    @Inject
    private BountyManager bountyManager;
    @Inject
    private PopupNotificationService popupNotificationService;
    @Inject
    private GameModeGuard gameModeGuard;

    // Phase 6: Overlay
    @Inject
    private EventOverlay eventOverlay;
    @Inject
    private Gson gson;

    // UI
    private BoomerangPanel panel;
    private NavigationButton navButton;

    // State
    private volatile boolean authenticated = false;
    private volatile boolean authenticating = false;

    // Name change tracking
    private final Map<String, String> nameChanges = new HashMap<>();
    private final LinkedBlockingQueue<NameChangeEntry> nameChangeQueue = new LinkedBlockingQueue<>();
    private boolean nameChangesSubmitted = false;

    /**
     * Parse the announcements JSON array from config into a List.
     */
    private List<String> parseAnnouncements() {
        try {
            String json = config.announcements();
            if (json == null || json.isEmpty()) {
                return Collections.emptyList();
            }
            List<String> result = gson.fromJson(json, new TypeToken<List<String>>(){}.getType());
            return result != null ? result : Collections.emptyList();
        } catch (Exception e) {
            log.warn("Failed to parse announcements config: {}", e.getMessage());
            return Collections.emptyList();
        }
    }

    @Override
    public void configure(Binder binder) {
        binder.install(new BoomerangBanditsModule());
    }

    @Override
    protected void startUp() {
        panel = injector.getInstance(BoomerangPanel.class);

        BufferedImage icon = ImageUtil.loadImageResource(
                getClass(), "/com/boomerangbandits/boomerang-icon.png"
        );

        navButton = NavigationButton.builder()
                .tooltip("Boomerang Bandits")
                .icon(icon)
                .priority(config.menuPriority())
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);

        // Wire group sync callback into admin panel
        panel.getAdminPanel().setOnGroupSync(this::triggerGroupSync);
        // Wire attendance tracker into admin panel
        panel.getAdminPanel().setAttendanceTracker(attendanceTracker, adminApi);

        // Register Phase 6 overlay
        overlayManager.add(eventOverlay);

        // Register notifiers
        registerNotifiers();

        log.info("Boomerang Bandits plugin started");
    }

    @Override
    protected void shutDown() {
        unregisterNotifiers();
        competitionScheduler.stop();
        clanRankSyncService.stop();
        overlayManager.remove(eventOverlay);
        clientToolbar.removeNavigation(navButton);
        configSyncService.stop();
        authenticated = false;

        log.info("Boomerang Bandits plugin stopped");
    }

    // ======================================================================
    // EVENT HANDLERS
    // ======================================================================

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        try {
            switch (event.getGameState()) {
                case LOGGED_IN:
                    // Guard: don't re-auth on world hop or reconnect
                    if (!authenticated) {
                        handleLogin();
                    } else {
                        // Still re-validate clan channel after world hop
                        // (clan channel reloads on hop)
                        executor.schedule(
                                () -> clientThread.invoke(() -> {
                                    if (clanValidator.validate()) {
                                        SwingUtilities.invokeLater(() -> panel.updateAdminVisibility());
                                    }
                                }),
                                5, java.util.concurrent.TimeUnit.SECONDS);
                    }
                    break;

                case LOGIN_SCREEN:
                case HOPPING:
                    attendanceTracker.onHoppingOrLogin();
                    if (authenticated) {
                        handleLogout();
                    }
                    break;

                case CONNECTION_LOST:
                    // Don't logout — player may reconnect
                    // But pause schedulers to avoid wasted requests
                    log.info("Connection lost, pausing schedulers");
                    competitionScheduler.stop();
                    configSyncService.stop();
                    break;
            }
        } catch (Exception e) {
            log.error("Error handling GameStateChanged", e);
        }
    }

    @Subscribe
    public void onClanChannelChanged(ClanChannelChanged event) {
        try {
            if (client.getGameState() == GameState.LOGGED_IN && !authenticated) {
                // Reset validator so a previous failed attempt doesn't block us
                clanValidator.reset();
                log.debug("Clan channel changed, attempting authentication in 2s");
                executor.schedule(
                        () -> clientThread.invoke(this::attemptAuthentication),
                        2, java.util.concurrent.TimeUnit.SECONDS
                );
            } else if (authenticated) {
                // Re-validate — player may have left the CC
                executor.schedule(
                        () -> clientThread.invoke(() -> {
                            if (!clanValidator.validate()) {
                                log.info("Player left clan channel — locking panel");
                                handleLogout();
                            } else {
                                SwingUtilities.invokeLater(() -> panel.updateAdminVisibility());
                            }
                        }),
                        2, java.util.concurrent.TimeUnit.SECONDS
                );
            }
        } catch (Exception e) {
            log.error("Error handling ClanChannelChanged", e);
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        try {
            if (!event.getGroup().equals(BoomerangBanditsConfig.GROUP)) {
                return;
            }

            // If the member code was just entered/changed while logged in, re-attempt auth immediately
            // so the player doesn't have to relog.
            if (event.getKey().equals("memberCode")
                    && client.getGameState() == GameState.LOGGED_IN
                    && !authenticated) {
                log.info("[Auth] Member code changed — re-attempting authentication");
                executor.submit(() -> clientThread.invoke(this::attemptAuthentication));
            }

            SwingUtilities.invokeLater(() -> {
                // Only refresh panel data if authenticated — avoids wasted API calls on startup
                if (authenticated) {
                    panel.refreshConfig();
                }
                // Announcements are local config — safe to update without auth
                panel.getHomePanel().updateAnnouncements(parseAnnouncements());
                panel.getHomePanel().updateBountySection(
                        configSyncService.getLatestConfig() != null
                                ? configSyncService.getLatestConfig().getBounties()
                                : null
                );
                // Also deliver new announcements to in-game chat
                inGameAnnouncementService.deliverAnnouncements(parseAnnouncements());

                // Update admin visibility if admin rank threshold changed
                if (event.getKey().equals("adminRankThreshold")) {
                    panel.updateAdminVisibility();
                }
            });
        } catch (Exception e) {
            log.error("Error handling ConfigChanged", e);
        }
    }

    @Subscribe
    public void onCommandExecuted(CommandExecuted event) {
        try {
            String command = event.getCommand().toLowerCase();

            switch (command) {
                case "syncranks":
                    if (!clanValidator.isAdmin()) {
                        log.debug("::syncranks blocked — player does not have admin rank");
                        return;
                    }
                    log.info("Manually syncing clan ranks to backend...");
                    clanRankSyncService.syncRanksManually(
                            response -> {
                                if (response.getInvalid() > 0 ||
                                        (response.getErrors() != null && !response.getErrors().isEmpty())) {
                                    log.warn("✅ Rank sync completed with {} errors", response.getInvalid());
                                } else {
                                    log.info("✅ Rank sync completed successfully");
                                }
                            },
                            error -> log.error("❌ Rank sync failed", error)
                    );
                    break;

                case "syncbandits":
                    if (!clanValidator.isAdmin()) {
                        log.debug("::syncbandits blocked — player does not have admin rank");
                        return;
                    }
                    log.info("Manual group sync triggered via ::syncbandits");
                    triggerGroupSync();
                    break;

                case "syncrsns":
                    if (!authenticated) {
                        log.debug("::syncrsns blocked — not authenticated");
                        return;
                    }
                    log.info("Manual name change sync triggered via ::syncrsns");
                    clientThread.invoke(this::submitNameChanges);
                    break;

            }
        } catch (Exception e) {
            log.error("Error handling command", e);
        }
    }

