    // ======================================================================
    // LOGIN / LOGOUT / AUTH
    // ======================================================================

    private void handleLogin() {
        RuneScapeProfileType profile = RuneScapeProfileType.getCurrent(client);
        log.info("Logged in — profile: {}, worldTypes: {}", profile, client.getWorldType());

        // Reset validation state on login
        clanValidator.reset();

        // Wait a moment for clan channel to load, then try authentication on the client thread
        executor.schedule(
                () -> clientThread.invoke(this::attemptAuthentication),
                2, java.util.concurrent.TimeUnit.SECONDS
        );
    }

    private void attemptAuthentication() {
        if (authenticated || authenticating) {
            return;
        }

        if (!clanValidator.validate()) {
            log.debug("Clan validation failed — features disabled");
            SwingUtilities.invokeLater(() ->
                    panel.getHomePanel().updateStatus("Not in clan", ColorScheme.LIGHT_GRAY_COLOR));
            return;
        }

        log.info("Clan validation successful");

        String playerName = client.getLocalPlayer() != null
                ? client.getLocalPlayer().getName()
                : "Unknown";

        SwingUtilities.invokeLater(() -> {
            panel.onLogin(playerName);
            // Show member code input now that clan validation passed
            panel.showMemberCodeInput();
        });

        authenticating = true;
        authenticate();
    }

    private void handleLogout() {
        authenticated = false;
        authenticating = false;
        configSyncService.stop();
        clanApi.resetDegradedState();
        clanApi.clearAuthToken();
        authInterceptor.clearCredentials();
        clanRankSyncService.setAuthToken(null);
        clanRankSyncService.setAccountHash(-1);
        womApi.setAuthToken(null);
        womApi.setAccountHash(-1);
        nameChangesSubmitted = false;
        inGameAnnouncementService.reset();
        bountyManager.reset();
        clanValidator.reset(); // Reset clan validation cache
        SwingUtilities.invokeLater(() -> {
            panel.getHomePanel().updateBountySection(null);
            panel.onLogout();
        });
    }

    private void authenticate() {
        if (client.getLocalPlayer() == null) {
            authenticating = false;
            return;
        }

        long accountHash = client.getAccountHash();
        if (accountHash == -1) {
            log.warn("[Auth] Skipping authentication - account hash not yet available");
            authenticating = false;
            return;
        }
        String rsn = client.getLocalPlayer().getName();

        // Member code is manually provided by the player (given by a clan admin).
        // If not set yet, still send the verify request — the backend will create
        // a pending member record and notify the admin. The plugin shows a
        // "waiting for member code" status until the admin sends it.
        String memberCode = config.memberCode();
        boolean hasMemberCode = memberCode != null && !memberCode.trim().isEmpty();

        String authToken = null;
        if (hasMemberCode) {
            // Derive auth token deterministically: HMAC-SHA256(key=memberCode, message=accountHash)
            // Reproducible on any install — player just re-enters their member code.
            try {
                Mac mac = Mac.getInstance("HmacSHA256");
                mac.init(new SecretKeySpec(memberCode.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
                byte[] hash = mac.doFinal(String.valueOf(accountHash).getBytes(StandardCharsets.UTF_8));
                authToken = Base64.getEncoder().encodeToString(hash);
            } catch (Exception e) {
                log.error("[Auth] Failed to compute auth token", e);
                return;
            }
            clanApi.setAuthToken(authToken);
        }

        // Set credentials on the interceptor — all services pick them up automatically
        authInterceptor.setCredentials(memberCode, authToken, accountHash);
        // Also keep ClanApiService in sync for its own internal state tracking
        clanApi.setAuthToken(authToken);
        clanApi.setAccountHash(accountHash);
        // Keep ClanRankSyncService in sync for explicit header injection
        clanRankSyncService.setAuthToken(authToken);
        clanRankSyncService.setAccountHash(accountHash);
        // Keep WomApiService in sync for name change submissions
        womApi.setAuthToken(authToken);
        womApi.setAccountHash(accountHash);

        final String finalAuthToken = authToken;

        assert rsn != null;
        clanApi.verifyMember(accountHash, rsn, finalAuthToken,
                authResponse -> {
                    if (authResponse.isSuccess()) {
                        authenticated = true;
                        authenticating = false;
                        log.info("Authenticated as: {} (code: {}...)",
                                rsn,
                                authResponse.getMemberCode().substring(0,
                                        Math.min(8, authResponse.getMemberCode().length()))
                        );

                        // Start config sync now that we have a member code
                        configSyncService.start(executor);
                        configSyncService.setOnConfigUpdated(() -> {
                            competitionScheduler.start(executor);

                            SwingUtilities.invokeLater(() -> {
                                panel.getHomePanel().updateBountySection(
                                        configSyncService.getLatestConfig() != null
                                                ? configSyncService.getLatestConfig().getBounties()
                                                : null
                                );
                                panel.getHomePanel().updateAnnouncements(parseAnnouncements());
                                inGameAnnouncementService.deliverAnnouncements(parseAnnouncements());
                            });
                        });

                        // Start clan rank sync
                        clanRankSyncService.start(executor);

                        // Start name change submission (every 30 min, 2 min initial delay)
                        executor.scheduleAtFixedRate(
                                () -> clientThread.invoke(BoomerangBanditsPlugin.this::submitNameChanges),
                                2, 30, TimeUnit.MINUTES);

                        SwingUtilities.invokeLater(() -> {
                            panel.onAuthenticated();
                            panel.getHomePanel().updateAnnouncements(parseAnnouncements());
                            panel.getHomePanel().updateBountySection(
                                    configSyncService.getLatestConfig() != null
                                            ? configSyncService.getLatestConfig().getBounties()
                                            : null
                            );
                            // Deliver announcements to in-game chat on first auth
                            inGameAnnouncementService.deliverAnnouncements(parseAnnouncements());
                            // Update admin visibility after authentication
                            panel.updateAdminVisibility();
                        });

                        // Trigger player update now that we're authenticated — must run on client thread
                        clientThread.invoke(() -> triggerPlayerUpdate(rsn, accountHash));
                    } else if (authResponse.isPending()) {
                        authenticating = false;
                        // Backend created the member row but hasn't issued a code yet.
                        // Admin will DM the member code — player must enter it in settings.
                        log.info("[Auth] Member registered as pending - awaiting member code from admin");
                        SwingUtilities.invokeLater(() ->
                                panel.getHomePanel().updateStatus(
                                        "Registered! Awaiting member code from admin", ColorScheme.LIGHT_GRAY_COLOR));
                    } else {
                        authenticating = false;
                        log.warn("Authentication failed: {}", authResponse.getError());
                    }
                },
                error -> {
                    authenticating = false;
                    log.warn("Authentication error: {}", error);
                    if (clanApi.isDegraded()) {
                        SwingUtilities.invokeLater(() -> panel.onDegraded());
                    }
                }
        );
    }

    // ======================================================================
    // WOM WRITE HELPERS
    // ======================================================================

    /**
     * Trigger a player update for the local player.
     * Called on login after auth, and can be called on manual refresh.
     */
    public void triggerPlayerUpdate(String rsn, long accountHash) {
        if (!gameModeGuard.isStandardWorld()) {
            log.info("[WOM] Skipping player update — non-standard world");
            return;
        }
        // Derive account type from the game client varbit rather than config
        int ironmanVarbit = client.getVarbitValue(net.runelite.api.gameval.VarbitID.IRONMAN);
        String accountType;
        if (ironmanVarbit == 1) {
            accountType = "ironman";
        } else if (ironmanVarbit == 2) {
            accountType = "hardcore_ironman";
        } else if (ironmanVarbit == 3) {
            accountType = "ultimate_ironman";
        } else if (ironmanVarbit == 4) {
            accountType = "group_ironman";
        } else if (ironmanVarbit == 5) {
            accountType = "hardcore_group_ironman";
        } else {
            accountType = "normal";
        }
        womApi.updatePlayer(rsn, accountHash, accountType,
                result -> log.info("[WOM] Player update queued for {} (job: {})", rsn, result.getData() != null ? result.getData().getJobId() : "?"),
                error -> log.warn("[WOM] Player update failed for {}: {}", rsn, error.getMessage())
        );
    }

    /**
     * Build SyncMember list from ClanSettings and call syncGroupMembers.
     * MUST be called on the client thread (uses ClanSettings).
     * Dispatches the HTTP call off-thread via executor.
     */
    public void triggerGroupSync() {
        clientThread.invoke(() -> {
            ClanSettings clanSettings = client.getClanSettings();
            if (clanSettings == null) {
                log.warn("[WOM] Cannot sync — clan settings not loaded");
                return;
            }

            java.util.List<net.runelite.api.clan.ClanMember> allMembers = clanSettings.getMembers();
            ArrayList<SyncMember> syncMembers = new ArrayList<>(allMembers.size());

            for (net.runelite.api.clan.ClanMember member : allMembers) {
                String rsn = member.getName();
                if (rsn.startsWith("[#")) continue; // skip bots

                String normalizedRsn = Text.toJagexName(rsn);
                net.runelite.api.clan.ClanTitle title = clanSettings.titleForRank(member.getRank());
                String role = title != null && title.getName() != null
                        ? title.getName().toLowerCase()
                        : "member";

                syncMembers.add(new SyncMember(normalizedRsn, role, "normal", null));
            }

            log.info("[WOM] Syncing {} clan members to backend (add_only)", syncMembers.size());

            womApi.syncGroupMembers(11575, "add_only", syncMembers,
                    result -> {
                        if (result.getData() != null) {
                            log.info("[WOM] Group sync done — added:{} updated:{} unchanged:{} invalid:{}",
                                    result.getData().getAdded(), result.getData().getUpdated(),
                                    result.getData().getUnchanged(), result.getData().getInvalid());
                        }
                    },
                    error -> log.error("[WOM] Group sync failed: {}", error.getMessage())
            );
        });
    }

    // ======================================================================
    // NAME CHANGE DETECTION (friends/ignore list — WOM pattern)
    // ======================================================================

    /**
     * Detects name changes from RuneLite's friends/ignore list.
     * Follows the WOM RuneLite plugin's proven approach.
     */
    @Subscribe
    public void onNameableNameChanged(NameableNameChanged event) {
        final Nameable nameable = event.getNameable();
        String name = nameable.getName();
        String prev = nameable.getPrevName();

        if (!isValidNameChange(prev, name)) {
            return;
        }

        NameChangeEntry entry = new NameChangeEntry(
                Text.toJagexName(prev), Text.toJagexName(name));

        // Don't re-register the same change
        String existing = nameChanges.get(entry.getNewName());
        if (existing != null && existing.equals(entry.getOldName())) {
            return;
        }

        nameChanges.put(entry.getNewName(), entry.getOldName());
        nameChangeQueue.add(entry);
        log.debug("[NameChange] Detected: {} -> {}", entry.getOldName(), entry.getNewName());
    }

    private boolean isValidNameChange(String prev, String curr) {
        return !(Strings.isNullOrEmpty(prev)
                || curr.equals(prev)
                || prev.startsWith("[#")
                || curr.startsWith("[#"));
    }

    /**
     * Submits queued name changes to the backend.
     * Called periodically via executor. Must run on client thread to access
     * friends/ignore list for validation.
     */
    private void submitNameChanges() {
        if (nameChangeQueue.isEmpty()) {
            nameChangesSubmitted = true;
            return;
        }

        if (!authenticated) {
            return;
        }

        // Validate queue entries against current friends/ignore list
        List<Nameable> friendIgnore = new ArrayList<>();
        Nameable[] friends = client.getFriendContainer().getMembers();
        Nameable[] ignored = client.getIgnoreContainer().getMembers();
        if (friends != null) {
            friendIgnore.addAll(Arrays.asList(friends));
        }
        if (ignored != null) {
            friendIgnore.addAll(Arrays.asList(ignored));
        }

        List<NameChangeEntry> validChanges = friendIgnore.stream()
                .filter(n -> isValidNameChange(n.getPrevName(), n.getName()))
                .map(n -> new NameChangeEntry(Text.toJagexName(n.getPrevName()), Text.toJagexName(n.getName())))
                .collect(Collectors.toList());

        // Remove stale entries no longer in friends/ignore list
        nameChangeQueue.removeIf(entry -> {
            if (!validChanges.contains(entry)) {
                nameChanges.remove(entry.getNewName(), entry.getOldName());
                return true;
            }
            return false;
        });

        if (nameChangeQueue.isEmpty()) {
            nameChangesSubmitted = true;
            return;
        }

        List<NameChangeEntry> batch = new ArrayList<>(nameChangeQueue);
        womApi.submitNameChanges(batch,
                result -> {
                    log.info("[NameChange] Submitted {} name changes to backend", batch.size());
                    nameChangeQueue.clear();
                    nameChangesSubmitted = true;
                },
                error -> log.warn("[NameChange] Failed to submit name changes: {}", error.getMessage())
        );
    }

    // ======================================================================
    // NOTIFIER REGISTRATION
    // ======================================================================

    private void registerNotifiers() {
        eventBus.register(cofferDepositSoundService);
        itemRenameManager.startUp();
        npcRenameManager.startUp();
        bountyManager.startUp();
    }

    private void unregisterNotifiers() {
        eventBus.unregister(cofferDepositSoundService);
        itemRenameManager.shutDown();
        npcRenameManager.shutDown();
        bountyManager.shutDown();
    }

    // ======================================================================
    // CLAN ROSTER LOGGING
    // ======================================================================

    /**
     * Log clan roster based on config settings.
     * Called when joining clan chat if enabled.
     * <p>
     * IMPORTANT: Must be called on the client thread (use clientThread.invoke())
     * because ClanSettings.titleForRank() requires client thread access.
     */
    @Provides
    BoomerangBanditsConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BoomerangBanditsConfig.class);
    }
}

package com.boomerangbandits.api;

import lombok.extern.slf4j.Slf4j;
import okhttp3.Interceptor;
import okhttp3.Request;
import okhttp3.Response;

import javax.inject.Singleton;
import java.io.IOException;

/**
 * OkHttp interceptor that injects auth headers on every outgoing request
 * to the Boomerang Bandits backend.
 * <p>
 * Headers injected (when set):
 * X-Member-Code  — identifies the member
 * X-Auth-Token   — HMAC-SHA256(memberCode, accountHash), proves ownership
 * X-Account-Hash — current OSRS account hash, required for alt-account support
 * <p>
 * Call {@link #setCredentials} after successful authentication and
 * {@link #clearCredentials} on logout.
 */
@Slf4j
@Singleton
public class AuthHeaderInterceptor implements Interceptor {

    private volatile String memberCode = null;
    private volatile String authToken = null;
    private volatile long accountHash = -1;

    public void setCredentials(String memberCode, String authToken, long accountHash) {
        this.memberCode = memberCode;
        this.authToken = authToken;
        this.accountHash = accountHash;
    }

    public void clearCredentials() {
        this.memberCode = null;
        this.authToken = null;
        this.accountHash = -1;
    }

    @Override
    public Response intercept(Chain chain) throws IOException {
        Request original = chain.request();

        // Only inject on requests to our backend
        String url = original.url().toString();
        if (!url.contains(ApiConstants.BACKEND_BASE_URL)) {
            return chain.proceed(original);
        }

        Request.Builder builder = original.newBuilder();

        if (memberCode != null && !memberCode.isEmpty()) {
            builder.header("X-Member-Code", memberCode);
        }
        if (authToken != null && !authToken.isEmpty()) {
            builder.header("X-Auth-Token", authToken);
        }
        if (accountHash != -1) {
            builder.header("X-Account-Hash", String.valueOf(accountHash));
        }

        return chain.proceed(builder.build());
    }
}

package com.boomerangbandits.api;

import lombok.extern.slf4j.Slf4j;
import okhttp3.MediaType;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/**
 * Centralized API configuration constants.
 * Single source of truth for all backend URLs and API settings.
 *
 * <p>The backend URL is injected at build time via Gradle resource filtering.
 * Override with: {@code ./gradlew compileJava -PbackendUrl=https://...}</p>
 */
@Slf4j
public final class ApiConstants {

    // ========================================================================
    // BACKEND API (Boomerang Bandits)
    // ========================================================================

    /**
     * Base URL for all Boomerang Bandits backend API calls.
     * Resolved from api.properties at class-load time.
     * Set at build time via -PbackendUrl Gradle property (defaults to production).
     */
    public static final String BACKEND_BASE_URL;

    static {
        String url = "https://api.boomerangbandits.cc"; // fallback
        try (InputStream is = ApiConstants.class.getResourceAsStream("/com/boomerangbandits/api.properties")) {
            if (is != null) {
                Properties props = new Properties();
                props.load(is);
                String loaded = props.getProperty("backend.base.url", "").trim();
                if (!loaded.isEmpty()) {
                    url = loaded;
                }
            }
        } catch (IOException e) {
            log.warn("Could not load api.properties, using fallback URL");
        }
        BACKEND_BASE_URL = url;
    }

    /**
     * User agent string for all backend API requests.
     * Format: PluginName/Version
     *
     * <p>Helps backend identify and track plugin requests for analytics and debugging.</p>
     */
    public static final String USER_AGENT = "BoomerangBanditsPlugin/1.0";

    // ========================================================================
    // COMMON
    // ========================================================================

    /**
     * Default result limit for paginated API endpoints (e.g. /wom/gains).
     * Covers the full clan roster with headroom. Update here if the clan grows significantly.
     */
    public static final int DEFAULT_API_LIMIT = 500;

    /**
     * JSON media type for HTTP request bodies.
     * Used by all services that send JSON payloads (POST/PUT requests).
     */
    public static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

    /**
     * Private constructor to prevent instantiation.
     * This is a utility class with only static constants.
     */
    private ApiConstants() {
        throw new AssertionError("Utility class - do not instantiate");
    }
}

package com.boomerangbandits.api;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.models.AuthResponse;
import com.boomerangbandits.api.models.LeaderboardEntry;
import com.boomerangbandits.api.models.PlayerProfile;
import com.boomerangbandits.api.models.PluginConfigResponse;
import com.google.gson.Gson;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;

/**
 * HTTP client for the Boomerang Bandits backend API.
 * <p>
 * All calls are async (OkHttp enqueue). Never blocks the game thread.
 * <p>
 * Error handling: tracks consecutive failures. After maxRetryAttempts,
 * enters degraded mode (stops retrying, uses cached data).
 */
@Slf4j
@Singleton
public class ClanApiService {

    private final AtomicInteger consecutiveFailures = new AtomicInteger(0);
    @Inject
    private @Named("boomerang") OkHttpClient httpClient;
    @Inject
    private Gson gson;
    @Inject
    private BoomerangBanditsConfig config;
    /**
     * -- GETTER --
     *
     */
    @Getter
    private volatile boolean degraded = false;

    /**
     * Auth token generated by the plugin on first login, persisted per RSN.
     * -- SETTER --
     *  Set the auth token after it has been loaded/generated by the plugin.
     *  Must be called before any authenticated requests are made.

     */
    @Setter
    private volatile String authToken = null;

    /**
     * Account hash of the currently logged-in player. Sent on every request.
     * -- SETTER --
     *  Set the account hash for the currently logged-in player.
     *  Sent as X-Account-Hash on every request so the backend can validate
     *  HMAC(member_code, account_hash) for alt account support.

     */
    @Setter
    private volatile long accountHash = -1;

    // ======================================================================
    // PUBLIC API METHODS
    // ======================================================================

    /**
     * POST /api/auth/verify
     * <p>
     * Authenticates the player. Sends account hash, RSN, account type, and optional owner tag.
     * Backend either finds existing member or auto-registers a new one.
     *
     * @param accountHash client.getAccountHash() value
     * @param rsn         player's RuneScape name
     * @param onSuccess   callback with AuthResponse on success
     * @param onError     callback with error message on failure
     */
    public void verifyMember(long accountHash, @Nonnull String rsn, String authToken,
                             @Nonnull Consumer<AuthResponse> onSuccess,
                             @Nonnull Consumer<String> onError) {
        String memberCode = config.memberCode();
        String json = gson.toJson(new VerifyRequest(rsn, authToken, memberCode));

        String url = ApiConstants.BACKEND_BASE_URL + "/auth/verify";
        log.info("[Auth] verifyMember url={} rsn={} hash={} mc={}... atLen={}",
                url, rsn, accountHash,
                memberCode != null && memberCode.length() > 8 ? memberCode.substring(0, 8) : memberCode,
                authToken != null ? authToken.length() : -1);

        Request.Builder builder = new Request.Builder()
                .url(url)
                .header("X-Account-Hash", String.valueOf(accountHash))
                .post(RequestBody.create(ApiConstants.JSON, json));

        if (memberCode != null && !memberCode.isEmpty()) {
            builder.header("X-Member-Code", memberCode);
        }
        if (authToken != null && !authToken.isEmpty()) {
            builder.header("X-Auth-Token", authToken);
        }

        Request request = builder.build();

        executeAsync(request, AuthResponse.class, onSuccess, onError);
    }

    /**
     * GET /api/plugin/config
     * <p>
     * Fetches remote plugin configuration. Called by ConfigSyncService.
     *
     * @param memberCode the authenticated member's code
     * @param onSuccess  callback with PluginConfigResponse on success
     * @param onError    callback with error message on failure
     */
    public void fetchPluginConfig(@Nonnull String memberCode,
                                  @Nonnull Consumer<PluginConfigResponse> onSuccess,
                                  @Nonnull Consumer<String> onError) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/plugin/config")
                .header("X-Member-Code", memberCode)
                .get()
                .build();

        executeAsync(request, PluginConfigResponse.Wrapper.class,
                wrapper -> {
                    if (wrapper != null && wrapper.getConfig() != null) {
                        onSuccess.accept(wrapper.getConfig());
                    } else {
                        onError.accept("Plugin config response missing 'config' field");
                    }
                },
                onError
        );
    }

    // ======================================================================
    // ERROR STATE
    // ======================================================================

    /**
     * Reset degraded state. Call this when connectivity is restored
     * (e.g., a successful call comes through).
     */
    public void resetDegradedState() {
        consecutiveFailures.set(0);
        degraded = false;
    }

    /**
     * Clear the auth token on logout so stale tokens aren't sent.
     */
    public void clearAuthToken() {
        this.authToken = null;
        this.accountHash = -1;
    }

    // ======================================================================
    // INTERNAL HTTP EXECUTION
    // ======================================================================

    private <T> void executeAsync(Request request, Class<T> responseType,
                                  Consumer<T> onSuccess, Consumer<String> onError) {
        if (degraded) {
            onError.accept("Service degraded — using cached data");
            return;
        }

        // Inject X-Auth-Token and X-Account-Hash on every request.
        // X-Account-Hash is required on all authenticated endpoints so the backend
        // can recompute HMAC(member_code, account_hash) — this supports alt accounts
        // sharing the same member_code.
        Request.Builder builder = request.newBuilder();
        if (authToken != null && !authToken.isEmpty()) {
            builder.header("X-Auth-Token", authToken);
        }
        if (accountHash != -1) {
            builder.header("X-Account-Hash", String.valueOf(accountHash));
        }
        request = builder.build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("[HTTP] onFailure url={} error={}", call.request().url(), e.getMessage());
                handleFailure(e.getMessage(), onError);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        String body = response.body() != null ? response.body().string() : "";
                        log.warn("[HTTP] {} {} → {} body={} "
                                        + "server={} cf-ray={} via={} cache={}",
                                call.request().method(),
                                call.request().url(),
                                response.code(),
                                body.length() > 200 ? body.substring(0, 200) : body,
                                response.header("server", "-"),
                                response.header("cf-ray", "-"),
                                response.header("via", "-"),
                                response.cacheResponse() != null ? "HIT" : "NETWORK");
                        handleFailure("HTTP " + response.code() + ": " + response.message(), onError);
                        return;
                    }

                    String body = response.body() != null ? response.body().string() : "";
                    T parsed = gson.fromJson(body, responseType);

                    // Reset failure counter on success
                    consecutiveFailures.set(0);
                    if (degraded) {
                        degraded = false;
                        log.info("Backend connectivity restored");
                    }

                    onSuccess.accept(parsed);
                } catch (Exception e) {
                    handleFailure("Parse error: " + e.getMessage(), onError);
                }
            }
        });
    }

    private void handleFailure(String message, Consumer<String> onError) {
        int failures = consecutiveFailures.incrementAndGet();
        int maxRetries = config.maxRetryAttempts();

        if (failures >= maxRetries && !degraded) {
            degraded = true;
            log.warn("Backend unreachable after {} attempts — entering degraded mode", failures);
        } else {
            log.warn("API call failed ({}/{}): {}", failures, maxRetries, message);
        }

        onError.accept(message);
    }

    // ======================================================================
    // PROFILE / LEADERBOARD / STATS METHODS
    // ======================================================================

    /**
     * GET /api/members/me
     * <p>
     * Fetches the authenticated player's full profile.
     * Requires X-Member-Code header.
     *
     * @param onSuccess callback with PlayerProfile on success
     * @param onError   callback with error message on failure
     */
    public void fetchPlayerProfile(@Nonnull Consumer<PlayerProfile> onSuccess,
                                   @Nonnull Consumer<String> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept("Not authenticated");
            return;
        }

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/members/me")
                .header("X-Member-Code", memberCode)
                .get()
                .build();

        executeAsync(request, PlayerProfile.class, onSuccess, onError);
    }

    /**
     * GET /api/leaderboard
     * <p>
     * Fetches the clan leaderboard (points-based).
     *
     * @param page      page number (1-based)
     * @param perPage   results per page
     * @param onSuccess callback with LeaderboardResponse on success
     * @param onError   callback with error message on failure
     */
    public void fetchLeaderboard(int page, int perPage,
                                 @Nonnull Consumer<LeaderboardResponse> onSuccess,
                                 @Nonnull Consumer<String> onError) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/leaderboard?page=" + page + "&per_page=" + perPage)
                .get()
                .build();

        executeAsync(request, LeaderboardResponse.class, onSuccess, onError);
    }

    /**
     * GET /api/stats/clan/daily-xp
     * <p>
     * Returns today's clan XP summary: top 3 players, top 3 skills, and active gainer count.
     * Uses UTC day boundaries. Requires X-Member-Code auth header.
     *
     * @param onSuccess callback with DailyXpResponse on success
     * @param onError   callback with error message on failure
     */
    public void fetchDailyXp(@Nonnull Consumer<com.boomerangbandits.api.models.DailyXpResponse> onSuccess,
                             @Nonnull Consumer<String> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept("Not authenticated");
            return;
        }

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/stats/clan/daily-xp")
                .header("X-Member-Code", memberCode)
                .get()
                .build();

        executeAsync(request, com.boomerangbandits.api.models.DailyXpResponse.class, onSuccess, onError);
    }

    /**
     * GET /api/members/me/player-challenges?incomplete=true
     * <p>
     * Fetches the current player's active (incomplete) challenge.
     * Requires X-Member-Code auth header.
     *
     * @param onSuccess callback with PlayerChallenge on success
     * @param onError   callback with error message on failure
     */
    public void fetchPlayerChallenge(
            @Nonnull Consumer<com.boomerangbandits.api.models.PlayerChallenge> onSuccess,
            @Nonnull Consumer<String> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept("Not authenticated");
            return;
        }

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/members/me/player-challenges?incomplete=true")
                .header("X-Member-Code", memberCode)
                .get()
                .build();

        executeAsync(request, com.boomerangbandits.api.models.PlayerChallenge.class, onSuccess, onError);
    }

    /**
     * GET /api/members/ranks/summary
     * <p>
     * Fetches rank summary (member count by rank).
     * Requires X-Member-Code header.
     *
     * @param includeZero whether to include ranks with zero members
     * @param onSuccess   callback with RankSummaryResponse on success
     * @param onError     callback with error message on failure
     */
    public void fetchRankSummary(boolean includeZero,
                                 @Nonnull Consumer<com.boomerangbandits.api.models.RankSummaryResponse> onSuccess,
                                 @Nonnull Consumer<String> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept("Not authenticated");
            return;
        }

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/members/ranks/summary?include_zero=" + includeZero)
                .header("X-Member-Code", memberCode)
                .get()
                .build();

        executeAsync(request, com.boomerangbandits.api.models.RankSummaryResponse.class, onSuccess, onError);
    }

    /**
     * POST /api/bounty/complete
     * <p>
     * Submits a bounty completion with screenshot proof.
     * Auth headers are injected automatically by {@link AuthHeaderInterceptor}.
     *
     * @param bountyId   server-assigned bounty ID
     * @param itemName   display name of the bounty item obtained
     * @param itemId     game item ID (0 if pet-only detection)
     * @param rsn        player's RuneScape name
     * @param screenshot base64-encoded PNG screenshot
     * @param onSuccess  callback with BountyCompletionResponse on success
     * @param onError    callback with error message on failure
     */
    public void submitBountyCompletion(@Nonnull String bountyId,
                                       @Nonnull String itemName,
                                       int itemId,
                                       @Nonnull String rsn,
                                       @Nonnull String screenshot,
                                       @Nonnull Consumer<com.boomerangbandits.api.models.BountyCompletionResponse> onSuccess,
                                       @Nonnull Consumer<String> onError) {
        String json = gson.toJson(new BountyCompletionRequest(bountyId, itemName, itemId, rsn, screenshot));

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/bounty/complete")
                .post(RequestBody.create(ApiConstants.JSON, json))
                .build();

        executeAsync(request, com.boomerangbandits.api.models.BountyCompletionResponse.class, onSuccess, onError);
    }

    // ======================================================================
    // INNER CLASSES (request bodies and response wrappers)
    // ======================================================================

    /**
     * Request body for POST /api/auth/verify
     */
    private static class VerifyRequest {
        private final String rsn;
        private final String authToken;
        private final String memberCode;

        VerifyRequest(String rsn, String authToken, String memberCode) {
            this.rsn = rsn;
            this.authToken = authToken;
            this.memberCode = memberCode;
        }
    }

    /**
     * Request body for POST /api/bounty/complete
     */
    private static class BountyCompletionRequest {
        private final String bountyId;
        private final String itemName;
        private final int itemId;
        private final String rsn;
        private final String screenshot;

        BountyCompletionRequest(String bountyId, String itemName, int itemId, String rsn, String screenshot) {
            this.bountyId = bountyId;
            this.itemName = itemName;
            this.itemId = itemId;
            this.rsn = rsn;
            this.screenshot = screenshot;
        }
    }

    /**
     * Wrapper for paginated leaderboard response.
     */
    @Setter
    @Getter
    public static class LeaderboardResponse {
        private List<LeaderboardEntry> leaderboard;
        private int total;
        private int page;
        private int pages;

    }
}

package com.boomerangbandits.api;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.models.ActiveEvent;
import com.boomerangbandits.api.models.ActiveEventResponse;
import com.boomerangbandits.util.CachedData;
import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.function.Consumer;

@Slf4j
@Singleton
public class ClanContentService {

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final BoomerangBanditsConfig config;

    // Cached data with TTLs
    private final CachedData<ActiveEvent> activeEventCache;

    @Inject
    public ClanContentService(
            @Named("boomerang") OkHttpClient httpClient,
            Gson gson,
            BoomerangBanditsConfig config
    ) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.config = config;

        this.activeEventCache = new CachedData<>(60 * 60 * 1_000L); // 1 hour
    }

    /**
     * Fetch active event for overlay
     */
    public void fetchActiveEvent(
            Consumer<ActiveEvent> onSuccess,
            Consumer<Exception> onError
    ) {
        // Check cache first
        if (activeEventCache.isFresh()) {
            log.debug("Returning cached active event");
            onSuccess.accept(activeEventCache.getData());
            return;
        }

        // Make API call
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/events/active")
                .get()
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to fetch active event", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        onError.accept(new IOException("HTTP " + response.code()));
                        return;
                    }

                    assert response.body() != null;
                    String body = response.body().string();
                    ActiveEventResponse resp = gson.fromJson(body, ActiveEventResponse.class);

                    if (resp == null || !resp.isSuccess()) {
                        onError.accept(new IOException("Invalid response"));
                        return;
                    }

                    ActiveEvent event = new ActiveEvent();
                    event.setActive(resp.isActive());
                    event.setEvents(resp.getEvents());

                    activeEventCache.update(event);
                    onSuccess.accept(event);

                } catch (Exception e) {
                    log.error("Failed to parse active event", e);
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * DELETE /api/events/active/{eventId} — deactivate/delete an active event.
     */
    public void deleteEvent(
            String memberCode,
            String eventId,
            Runnable onSuccess,
            Consumer<Exception> onError
    ) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/events/active/" + eventId)
                .header("X-Member-Code", memberCode)
                .delete()
                .build();

        executeWrite(request, "delete event", onSuccess, onError);
    }

    /**
     * POST /api/events/active — create a new active event.
     */
    public void createEvent(
            String memberCode,
            String payload,
            Runnable onSuccess,
            Consumer<Exception> onError
    ) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/events/active")
                .header("X-Member-Code", memberCode)
                .post(RequestBody.create(ApiConstants.JSON, payload))
                .build();

        executeWrite(request, "create event", onSuccess, onError);
    }

    /**
     * PATCH /api/events/active/{eventId} — update an existing active event.
     */
    public void patchEvent(
            String memberCode,
            String eventId,
            String payload,
            Runnable onSuccess,
            Consumer<Exception> onError
    ) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/events/active/" + eventId)
                .header("X-Member-Code", memberCode)
                .patch(RequestBody.create(ApiConstants.JSON, payload))
                .build();

        executeWrite(request, "patch event", onSuccess, onError);
    }

    /**
     * Shared async executor for write operations (create/update/delete).
     * Invalidates the active event cache on success.
     */
    private void executeWrite(Request request, String operation,
                              Runnable onSuccess, Consumer<Exception> onError) {
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to {}", operation, e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        String errorBody = response.body() != null ? response.body().string() : "(no body)";
                        log.warn("{} failed HTTP {}: {}", operation, response.code(), errorBody);
                        onError.accept(new IOException("HTTP " + response.code() + ": " + errorBody));
                        return;
                    }
                    activeEventCache.invalidate();
                    onSuccess.run();
                } catch (Exception e) {
                    log.error("Error handling {} response", operation, e);
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * Invalidate all caches
     */
    public void invalidateCaches() {
        activeEventCache.invalidate();
        log.debug("All content caches invalidated");
    }
}

