package com.boomerangbandits.api;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.models.GroupSyncResponse;
import com.boomerangbandits.api.models.PlayerUpdateResponse;
import com.boomerangbandits.api.models.NameChangeEntry;
import com.boomerangbandits.api.models.WomCompetition;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.List;
import java.util.function.Consumer;

/**
 * WiseOldMan API client (via Backend Proxy).
 * Fetches competition data for the Boomerang Bandits clan through the backend API.
 * <p>
 * The backend proxies WOM API calls and provides Redis caching for better performance.
 * Backend handles group ID (11575), caching, rate limiting, and stale data fallback.
 * <p>
 * All HTTP calls use enqueue() (async). Never call execute().
 * <p>
 * Backend API: /api/wom/*
 * Original WOM API docs: <a href="https://docs.wiseoldman.net/">WiseOldMan</a>
 */
@Slf4j
@Singleton
public class WomApiService {

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final BoomerangBanditsConfig config;
    @Setter
	private volatile String authToken;
    @Setter
	private volatile long accountHash = -1;

    @Inject
    public WomApiService(@Named("boomerangWom") OkHttpClient httpClient, Gson gson, BoomerangBanditsConfig config) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.config = config;
    }

    /**
     * Fetch all competitions for the group.
     * Backend handles caching and returns fresh data.
     * Uses active_only=true to fetch only currently active competitions.
     */
    public void fetchCompetitions(@Nonnull Consumer<List<WomCompetition>> onSuccess,
                                  @Nonnull Consumer<Exception> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept(new IllegalStateException("Not authenticated"));
            return;
        }

        String url = ApiConstants.BACKEND_BASE_URL + "/wom/competitions?active_only=true";
        log.debug("Fetching competitions from backend API: {}", url);
        Request request = buildRequest(url);

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to fetch competitions from backend", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        log.warn("Backend competitions returned HTTP {}", response.code());
                        onError.accept(new IOException("HTTP " + response.code()));
                        return;
                    }

                    String body = response.body().string();
                    log.debug("Backend competitions response body length: {}", body.length());
                    Type listType = new TypeToken<List<WomCompetition>>() {
                    }.getType();
                    List<WomCompetition> competitions = gson.fromJson(body, listType);
                    log.debug("Parsed {} competitions from backend API", competitions != null ? competitions.size() : 0);
                    onSuccess.accept(competitions);
                } catch (Exception e) {
                    log.error("Failed to parse competitions response", e);
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * Fetch a single competition with full participant data.
     * Backend handles caching and returns fresh data.
     */
    public void fetchCompetitionDetails(int competitionId,
                                        @Nonnull Consumer<WomCompetition> onSuccess,
                                        @Nonnull Consumer<Exception> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept(new IllegalStateException("Not authenticated"));
            return;
        }

        String url = ApiConstants.BACKEND_BASE_URL + "/wom/competitions/" + competitionId;
        Request request = buildRequest(url);

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to fetch competition {} from backend", competitionId, e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        onError.accept(new IOException("HTTP " + response.code()));
                        return;
                    }

                    String body = response.body().string();
                    WomCompetition competition = gson.fromJson(body, WomCompetition.class);
                    onSuccess.accept(competition);
                } catch (Exception e) {
                    log.error("Failed to parse competition {} response", competitionId, e);
                    onError.accept(e);
                }
            }
        });
    }

    // ======================================================================
    // WRITE ENDPOINTS (require X-Member-Code, organiser+ rank)
    // ======================================================================

    /**
     * POST /api/wom/players/update
     * <p>
     * Enqueues a background poll for one account. Non-blocking (202 Accepted).
     * Retry on 503 (queue unavailable). Do not retry on 400/401/403.
     *
     * @param username    player's RSN (required)
     * @param accountHash client.getAccountHash() — pass 0 if unavailable
     * @param accountType e.g. "normal", "ironman"
     * @param onSuccess   callback with PlayerUpdateResponse on 202
     * @param onError     callback with exception on failure
     */
    public void updatePlayer(@Nonnull String username, long accountHash,
                             @Nonnull String accountType,
                             @Nonnull Consumer<PlayerUpdateResponse> onSuccess,
                             @Nonnull Consumer<Exception> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept(new IllegalStateException("Not authenticated"));
            return;
        }

        String ownerTag = null; // ownerTag removed from config — no longer used
        String json = gson.toJson(new PlayerUpdateRequest(username, accountHash, accountType, ownerTag, false));

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/wom/players/update")
                .addHeader("X-Member-Code", memberCode)
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .post(RequestBody.create(ApiConstants.JSON, json))
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to queue player update for {}", username, e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (response.code() == 202) {
                        PlayerUpdateResponse result = gson.fromJson(
                                response.body().string(), PlayerUpdateResponse.class);
                        onSuccess.accept(result);
                    } else {
                        String body = response.body() != null ? response.body().string() : "";
                        onError.accept(new IOException("HTTP " + response.code() + ": " + body));
                    }
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * POST /api/wom/groups/{groupId}/sync
     * <p>
     * Syncs the clan roster to backend member/account state.
     * mode="add_only" upserts listed members without deactivating missing ones.
     * mode="overwrite" treats the payload as source of truth.
     *
     * @param groupId   backend group ID (e.g. 11575)
     * @param mode      "add_only" or "overwrite"
     * @param members   list of members to sync
     * @param onSuccess callback with GroupSyncResponse on 200
     * @param onError   callback with exception on failure
     */
    public void syncGroupMembers(int groupId, @Nonnull String mode,
                                 @Nonnull List<SyncMember> members,
                                 @Nonnull Consumer<GroupSyncResponse> onSuccess,
                                 @Nonnull Consumer<Exception> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept(new IllegalStateException("Not authenticated"));
            return;
        }

        String json = gson.toJson(new GroupSyncRequest(mode, members));

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/wom/groups/" + groupId + "/sync")
                .addHeader("X-Member-Code", memberCode)
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .post(RequestBody.create(ApiConstants.JSON, json))
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to sync group {} members", groupId, e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        String body = response.body() != null ? response.body().string() : "";
                        if (response.code() == 403) {
                            onError.accept(new SecurityException("Insufficient rank to sync group members"));
                        } else if (response.code() == 404) {
                            onError.accept(new IllegalArgumentException("Group ID " + groupId + " not found on backend"));
                        } else {
                            onError.accept(new IOException("HTTP " + response.code() + ": " + body));
                        }
                        return;
                    }
                    GroupSyncResponse result = gson.fromJson(
                            response.body().string(), GroupSyncResponse.class);
                    if (result.getData() != null && result.getData().getInvalid() > 0) {
                        log.warn("Group sync partial: {} invalid rows", result.getData().getInvalid());
                    }
                    onSuccess.accept(result);
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * POST /api/wom/names/bulk
     * <p>
     * Submits detected name changes to the backend in bulk.
     * Name changes are detected via RuneLite's NameableNameChanged event
     * (friends/ignore list) following the WOM plugin pattern.
     *
     * @param nameChanges list of old→new name pairs to submit
     * @param onSuccess   callback with response body on 200
     * @param onError     callback with exception on failure
     */
    public void submitNameChanges(@Nonnull List<NameChangeEntry> nameChanges,
                                  @Nonnull Consumer<String> onSuccess,
                                  @Nonnull Consumer<Exception> onError) {
        String memberCode = config.memberCode();
        if (memberCode == null || memberCode.isEmpty()) {
            onError.accept(new IllegalStateException("Not authenticated"));
            return;
        }

        String json = gson.toJson(nameChanges);
        log.info("Submitting {} name changes to backend", nameChanges.size());

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/wom/names/bulk")
                .post(RequestBody.create(ApiConstants.JSON, json))
                .header("X-Member-Code", memberCode)
                .header("X-Account-Hash", String.valueOf(accountHash))
                .header("X-Auth-Token", authToken != null ? authToken : "")
                .header("Content-Type", "application/json")
                .header("User-Agent", ApiConstants.USER_AGENT)
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to submit name changes", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    String body = response.body() != null ? response.body().string() : "";
                    if (response.isSuccessful()) {
                        log.info("Name changes submitted successfully");
                        onSuccess.accept(body);
                    } else {
                        log.warn("Name change submission returned HTTP {}: {}", response.code(), body);
                        onError.accept(new IOException("HTTP " + response.code() + ": " + body));
                    }
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

	// ======================================================================
    // REQUEST DTOs (write endpoints)
    // ======================================================================

    @Nonnull
    private Request buildRequest(@Nonnull String url) {
        return new Request.Builder()
                .url(url)
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .build();
    }

    /**
     * Request body for POST /api/wom/players/update
     */
    public static class PlayerUpdateRequest {
        private final String username;
        private final long accountHash;
        private final String accountType;
        private final String ownerTag;
        private final boolean force;

        public PlayerUpdateRequest(String username, long accountHash, String accountType,
                                   String ownerTag, boolean force) {
            this.username = username;
            this.accountHash = accountHash;
            this.accountType = accountType;
            this.ownerTag = ownerTag;
            this.force = force;
        }
    }

    /**
     * Request body for POST /api/wom/groups/{groupId}/sync
     */
    public static class GroupSyncRequest {
        private final String mode;
        private final List<SyncMember> members;

        public GroupSyncRequest(String mode, List<SyncMember> members) {
            this.mode = mode;
            this.members = members;
        }
    }

    /**
     * A single member entry in a group sync request
     */
    public static class SyncMember {
        private final String username;
        private final String role;
        private final String accountType;
        private final String ownerTag;

        public SyncMember(String username, String role, String accountType, String ownerTag) {
            this.username = username;
            this.role = role;
            this.accountType = accountType;
            this.ownerTag = ownerTag;
        }
    }
}

package com.boomerangbandits.api;

import com.boomerangbandits.BoomerangBanditsConfig;
import com.boomerangbandits.api.models.AttendanceEntry;
import com.boomerangbandits.api.models.AttendanceResult;
import com.boomerangbandits.api.models.RankChange;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.annotation.Nonnull;
import javax.inject.Inject;
import javax.inject.Named;
import javax.inject.Singleton;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.List;
import java.util.function.Consumer;

/**
 * API service for admin-only endpoints.
 * All requests include X-Member-Code header for authentication.
 * Backend verifies admin rank server-side.
 * <p>
 * Separated from ClanApiService to keep admin concerns isolated.
 */
@Slf4j
@Singleton
public class AdminApiService {

    private final OkHttpClient httpClient;
    private final Gson gson;
    private final BoomerangBanditsConfig config;

    @Inject
    public AdminApiService(@Named("boomerang") OkHttpClient httpClient, Gson gson, BoomerangBanditsConfig config) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.config = config;
    }

    // =========================================================================
    // Attendance Ingestion
    // =========================================================================

    /**
     * Submit structured attendance data for backend processing.
     * Backend matches RSNs to members and awards attendance points.
     *
     * @param eventName       optional event name for record-keeping
     * @param durationSeconds total event duration in seconds
     * @param entries         per-member attendance data from EventAttendanceTracker
     */
    public void submitAttendance(@Nonnull String eventName,
                                 int durationSeconds,
                                 @Nonnull java.util.List<AttendanceEntry> entries,
                                 @Nonnull Consumer<AttendanceResult> onSuccess,
                                 @Nonnull Consumer<Exception> onError) {
        String json = gson.toJson(new AttendanceRequest(eventName, durationSeconds, entries));

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/admin/attendance/ingest")
                .addHeader("X-Member-Code", config.memberCode())
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .post(RequestBody.create(ApiConstants.JSON, json))
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to submit attendance", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        String body = response.body() != null ? response.body().string() : "";
                        if (response.code() == 403) {
                            onError.accept(new SecurityException("Insufficient rank for admin actions"));
                        } else {
                            onError.accept(new IOException("HTTP " + response.code() + ": " + body));
                        }
                        return;
                    }
                    AttendanceResult result = gson.fromJson(
                            response.body().string(), AttendanceResult.class
                    );
                    onSuccess.accept(result);
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

    // =========================================================================
    // Rank Changes
    // =========================================================================

    /**
     * Fetch pending rank changes.
     * Backend: GET /api/admin/rank-changes/pending
     */
    public void fetchPendingRankChanges(@Nonnull Consumer<List<RankChange>> onSuccess,
                                        @Nonnull Consumer<Exception> onError) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/admin/rank-changes/pending")
                .addHeader("X-Member-Code", config.memberCode())
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to fetch rank changes", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        handleErrorResponse(response, onError);
                        return;
                    }
                    Type listType = new TypeToken<RankChangesResponse>() {
                    }.getType();
                    assert response.body() != null;
                    RankChangesResponse result = gson.fromJson(
                            response.body().string(), listType
                    );
                    onSuccess.accept(result.rankChanges);
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * Propose a new rank change for a member.
     * Backend: POST /api/admin/rank-changes
     * Immediately updates website rank and queues a pending item for in-game processing.
     */
    public void proposeRankChange(@Nonnull String memberRsn,
                                  @Nonnull String newRank,
                                  @Nonnull String reason,
                                  @Nonnull Consumer<RankChange> onSuccess,
                                  @Nonnull Consumer<Exception> onError) {
        String json = gson.toJson(new ProposeRankChangeRequest(memberRsn, newRank, reason));

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/admin/rank-changes")
                .addHeader("X-Member-Code", config.memberCode())
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .post(RequestBody.create(ApiConstants.JSON, json))
                .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to propose rank change", e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        handleErrorResponse(response, onError);
                        return;
                    }
                    ProposeRankChangeResponse result = gson.fromJson(
                            response.body().string(), ProposeRankChangeResponse.class);
                    onSuccess.accept(result.rankChange);
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

    /**
     * Mark a pending rank change as done in-game.
     * Backend: POST /api/admin/rank-changes/{id}/actualize
     */
    public void actualizeRankChange(@Nonnull String rankChangeId,
                                    @Nonnull Consumer<Boolean> onSuccess,
                                    @Nonnull Consumer<Exception> onError) {
        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/admin/rank-changes/" + rankChangeId + "/actualize")
                .addHeader("X-Member-Code", config.memberCode())
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .post(RequestBody.create(ApiConstants.JSON, "{}"))
                .build();

        executeSimplePost(request, onSuccess, onError);
    }

    // =========================================================================
    // Announcements
    // =========================================================================

    /**
     * Update the announcement message.
     * Backend: POST /api/admin/announcement
     */
    public void updateAnnouncement(@Nonnull String message,
                                   @Nonnull Consumer<Boolean> onSuccess,
                                   @Nonnull Consumer<Exception> onError) {
        String json = gson.toJson(new AnnouncementRequest(message));

        Request request = new Request.Builder()
                .url(ApiConstants.BACKEND_BASE_URL + "/admin/announcement")
                .addHeader("X-Member-Code", config.memberCode())
                .addHeader("User-Agent", ApiConstants.USER_AGENT)
                .post(RequestBody.create(ApiConstants.JSON, json))
                .build();

        executeSimplePost(request, onSuccess, onError);
    }

    // =========================================================================
    // Helpers
    // =========================================================================

    private void executeSimplePost(Request request,
                                   Consumer<Boolean> onSuccess,
                                   Consumer<Exception> onError) {
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Admin request failed: {}", request.url(), e);
                onError.accept(e);
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException {
                try (response) {
                    if (!response.isSuccessful()) {
                        handleErrorResponse(response, onError);
                        return;
                    }
                    onSuccess.accept(true);
                } catch (Exception e) {
                    onError.accept(e);
                }
            }
        });
    }

    private void handleErrorResponse(Response response, Consumer<Exception> onError) throws IOException {
        String body = response.body() != null ? response.body().string() : "";
        if (response.code() == 403) {
            onError.accept(new SecurityException("Insufficient rank for admin actions"));
        } else {
            onError.accept(new IOException("HTTP " + response.code() + ": " + body));
        }
    }

    // Request DTOs
    private static class AttendanceRequest {
        final String eventName;
        final int durationSeconds;
        final java.util.List<AttendanceEntry> entries;

        AttendanceRequest(String eventName, int durationSeconds, java.util.List<AttendanceEntry> entries) {
            this.eventName = eventName;
            this.durationSeconds = durationSeconds;
            this.entries = entries;
        }
    }

    private static class AnnouncementRequest {
        final String message;

        AnnouncementRequest(String message) {
            this.message = message;
        }
    }

    private static class ProposeRankChangeRequest {
        final String memberRsn;
        final String newRank;
        final String reason;

        ProposeRankChangeRequest(String memberRsn, String newRank, String reason) {
            this.memberRsn = memberRsn;
            this.newRank = newRank;
            this.reason = reason;
        }
    }

    private static class ProposeRankChangeResponse {
        boolean success;
        RankChange rankChange;
    }

    private static class RankChangesResponse {
        List<RankChange> rankChanges;
    }
}

package com.boomerangbandits.util;

import javax.annotation.Nullable;

/**
 * Generic cache wrapper with TTL.
 * Thread-safe for read after write (volatile fields).
 * <p>
 * Usage:
 * CachedData<List<WomCompetition>> cache = new CachedData<>(5 * 60 * 1000L);
 * if (cache.isFresh()) return cache.getData();
 * // else fetch and call cache.update(newData);
 */
public class CachedData<T> {
    private final long ttlMs;
    @Nullable
    private volatile T data;
    private volatile long lastUpdated;

    public CachedData(long ttlMs) {
        if (ttlMs <= 0) {
            throw new IllegalArgumentException("TTL must be positive");
        }
        this.ttlMs = ttlMs;
        this.lastUpdated = 0;
    }

    public boolean isFresh() {
        return data != null && (System.currentTimeMillis() - lastUpdated) < ttlMs;
    }

    @Nullable
    public T getData() {
        return data;
    }

    public void update(@Nullable T newData) {
        this.data = newData;
        this.lastUpdated = System.currentTimeMillis();
    }

    public void invalidate() {
        this.lastUpdated = 0;
    }

    public long getAgeMs() {
        return System.currentTimeMillis() - lastUpdated;
    }
}

package com.boomerangbandits.util;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.WidgetNode;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import javax.inject.Singleton;
import javax.annotation.Nullable;
import java.awt.Color;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;

/**
 * Shows native OSRS notification popups (same widget as collection log notifications).
 * Uses interface 660 + script 3343 (NOTIFICATION_DISPLAY_INIT).
 * <p>
 * Popups are queued and processed one at a time on the game tick.
 * Call {@link #processQueue()} from onGameTick to drain the queue.
 */
@Slf4j
@Singleton
public class PopupNotificationService {
    private static final int SCRIPT_ID = 3343; // NOTIFICATION_DISPLAY_INIT
    private static final int INTERFACE_ID = 660;
    // Widget child 3 = title text (verified in-game)
    private static final int CHILD_TITLE_TEXT = 3;

    private static final int RESIZABLE_CLASSIC_LAYOUT = WidgetUtil.packComponentId(161, 13);
    private static final int RESIZABLE_MODERN_LAYOUT = WidgetUtil.packComponentId(164, 13);
    private static final int FIXED_CLASSIC_LAYOUT = WidgetUtil.packComponentId(548, 42);

    private static final Color DEFAULT_GOLD = new Color(0xFF, 0xD7, 0x00);

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    private final Queue<PopupData> popupQueue = new ConcurrentLinkedQueue<>();

    /**
     * Queue a popup with full customisation.
     *
     * @param title      popup title line
     * @param message    popup body line
     * @param color      text color for both title and body (passed to script), or null for default gold
     * @param titleColor override color for title text only (post-modified via child 3), or null to match color
     * @param fontId     OSRS font ID, or -1 to keep default (reserved for future use)
     */
    public void showPopup(String title, String message,
                          @Nullable Color color, @Nullable Color titleColor, int fontId) {
        popupQueue.offer(new PopupData(title, message, color, titleColor, fontId));
    }

    /**
     * Queue a popup with separate title color, default font.
     */
    public void showPopup(String title, String message,
                          @Nullable Color color, @Nullable Color titleColor) {
        showPopup(title, message, color, titleColor, -1);
    }

    /**
     * Queue a popup with a single color for both title and body.
     */
    public void showPopup(String title, String message, @Nullable Color color) {
        showPopup(title, message, color, null, -1);
    }

    /**
     * Queue a popup with default gold color.
     */
    public void showPopup(String title, String message) {
        showPopup(title, message, DEFAULT_GOLD, null, -1);
    }

    /**
     * Call this from onGameTick. Processes one popup per tick if no popup is currently visible.
     */
    public void processQueue() {
        // Wait for any existing popup to close
        if (client.getWidget(INTERFACE_ID, 1) != null) {
            return;
        }

        if (popupQueue.isEmpty()) {
            return;
        }

        PopupData data = popupQueue.poll();
        if (data == null) {
            return;
        }

        try {
            WidgetNode widgetNode = client.openInterface(getComponentId(), INTERFACE_ID, WidgetModalMode.MODAL_CLICKTHROUGH);

            Color color = data.color != null ? data.color : DEFAULT_GOLD;
            client.runScript(SCRIPT_ID, data.title, data.message, toRgbInt(color));

            // Post-modify: override title color if specified (child 3 = title text)
            if (data.titleColor != null) {
                Widget titleWidget = client.getWidget(INTERFACE_ID, CHILD_TITLE_TEXT);
                if (titleWidget != null) {
                    titleWidget.setTextColor(toRgbInt(data.titleColor));
                }
            }
            Widget widget = client.getWidget(INTERFACE_ID, 1);
            clientThread.invokeLater(() -> {
                if (widget != null && widget.getWidth() > 0) {
                    return false; // still visible, keep waiting
                }
                client.closeInterface(widgetNode, true);
                return true;
            });
        } catch (Exception e) {
            log.warn("Failed to show popup notification", e);
        }
    }

    private int getComponentId() {
        return client.isResized()
                ? (client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                    ? RESIZABLE_MODERN_LAYOUT
                    : RESIZABLE_CLASSIC_LAYOUT)
                : FIXED_CLASSIC_LAYOUT;
    }

    private static int toRgbInt(Color color) {
        return color.getRed() << 16 | color.getGreen() << 8 | color.getBlue();
    }

    private static class PopupData {
        final String title;
        final String message;
        final Color color;
        final Color titleColor;
        final int fontId;

        PopupData(String title, String message,
                 @Nullable Color color, @Nullable Color titleColor, int fontId) {
            this.title = title;
            this.message = message;
            this.color = color;
            this.titleColor = titleColor;
            this.fontId = fontId;
        }
    }
}

package com.boomerangbandits.util;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.DrawManager;

import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.util.Base64;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Slf4j
@Singleton
public class ScreenshotService
{
	private static final float JPEG_QUALITY = 0.92f;
	private static final int MAX_WIDTH = 1600;

	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private DrawManager drawManager;
	@Inject private ScheduledExecutorService executor;

	/**
	 * Captures a privacy-safe screenshot with chat/PM hidden.
	 * Returns a CompletableFuture containing the base64-encoded JPEG string,
	 * or null if capture fails. Times out after 10 seconds.
	 */
	public CompletableFuture<String> captureScreenshot()
	{
		CompletableFuture<String> result = new CompletableFuture<>();

		clientThread.invokeLater(() ->
		{
			Widget pm = client.getWidget(InterfaceID.PmChat.CONTAINER);

			boolean pmWasVisible = pm != null && !pm.isHidden();

			if (pmWasVisible) pm.setHidden(true);

			try
			{
				drawManager.requestNextFrameListener(image ->
				{
					try
					{
						executor.submit(() ->
						{
							if (image == null)
							{
								result.complete(null);
								return;
							}
							try
							{
								BufferedImage screenshot = toBufferedImage(image);
								screenshot = resizeIfNeeded(screenshot);
								result.complete(compressAndEncode(screenshot));
							}
							catch (Exception e)
							{
								log.error("Error processing screenshot", e);
								result.complete(null);
							}
						});
					}
					finally
					{
						// Always restore widgets on client thread after frame capture
						if (pmWasVisible)
						{
							clientThread.invoke(() ->
							{
								if (pm != null) pm.setHidden(false);
								return true;
							});
						}
					}
				});
			}
			catch (Exception e)
			{
				// requestNextFrameListener failed — restore widgets immediately (already on client thread)
				if (pmWasVisible && pm != null) pm.setHidden(false);
				log.error("Failed to request screenshot frame", e);
				result.complete(null);
			}
		});

		return result.orTimeout(10, TimeUnit.SECONDS);
	}

	private BufferedImage toBufferedImage(Image image)
	{
		if (image instanceof BufferedImage)
		{
			return (BufferedImage) image;
		}

		BufferedImage buffered = new BufferedImage(
			image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
		Graphics2D g = buffered.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();
		return buffered;
	}

	private BufferedImage resizeIfNeeded(BufferedImage image)
	{
		if (image.getWidth() <= MAX_WIDTH)
		{
			return image;
		}

		double scale = (double) MAX_WIDTH / image.getWidth();
		int newHeight = (int) (image.getHeight() * scale);

		BufferedImage resized = new BufferedImage(MAX_WIDTH, newHeight, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = resized.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		g.drawImage(image, 0, 0, MAX_WIDTH, newHeight, null);
		g.dispose();
		return resized;
	}

	private String compressAndEncode(BufferedImage image) throws Exception
	{
		ByteArrayOutputStream baos = new ByteArrayOutputStream(65536);

		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		ImageWriteParam param = writer.getDefaultWriteParam();
		param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
		param.setCompressionQuality(JPEG_QUALITY);

		try (ImageOutputStream ios = ImageIO.createImageOutputStream(baos))
		{
			writer.setOutput(ios);
			writer.write(null, new IIOImage(image, null, null), param);
		}
		finally
		{
			writer.dispose();
		}

		byte[] bytes = baos.toByteArray();
		log.debug("Screenshot captured: {}x{}, {} KB", image.getWidth(), image.getHeight(), bytes.length / 1024);

		return Base64.getEncoder().encodeToString(bytes);
	}
}

package com.boomerangbandits.util;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WorldType;
import net.runelite.client.config.RuneScapeProfileType;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class GameModeGuard {

    @Inject
    private Client client;

    /**
     * Returns true only if the player is on a standard OSRS world.
     * Blocks: Leagues (SEASONAL), Deadman Mode (DEADMAN), Fresh Start (FRESH_START_WORLD),
     * Beta worlds (BETA_WORLD), PvP Arena, Quest Speedrunning, and all other non-STANDARD profiles.
     * Also explicitly blocks Tournament worlds (WorldType.TOURNAMENT_WORLD) which incorrectly
     * return RuneScapeProfileType.STANDARD.
     */
    public boolean isStandardWorld() {
        if (client.getWorldType().isEmpty()) {
            log.debug("[GameModeGuard] Empty world types detected");
            return false;
        }

        RuneScapeProfileType profile = RuneScapeProfileType.getCurrent(client);
        if (profile != RuneScapeProfileType.STANDARD) {
            log.debug("[GameModeGuard] Non-standard profile detected: {}, worldTypes: {}",
                    profile, client.getWorldType());
            return false;
        }
        if (client.getWorldType().contains(WorldType.TOURNAMENT_WORLD)) {
            log.debug("[GameModeGuard] Tournament world detected, worldTypes: {}",
                    client.getWorldType());
            return false;
        }
        return true;
    }
}

package com.boomerangbandits.util;

import com.boomerangbandits.BoomerangBanditsConfig;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.*;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Validates that the local player is a member of the Boomerang Bandits clan.
 * <p>
 * Behaviour: If validation fails, the plugin silently disables features.
 * No error UI is shown — the plugin simply does nothing for non-clan members.
 * <p>
 * Throttling: After initial failure, retries every 5 seconds for 1 minute, then gives up.
 */
@Slf4j
@Singleton
public class ClanValidator {

    /**
     * The in-game clan name. Case-insensitive match.
     */
    private static final String CLAN_NAME = "boomerangrs";

    /**
     * Minimum clan rank required. 0 = any member (including guests with rank).
     * Uses ClanRank integer values, not ordinals.
     */
    private static final int MINIMUM_CLAN_RANK = 0;

    /**
     * Clan title names (lowercase) that grant admin access to the plugin.
     * Matched against the custom title returned by ClanSettings.titleForRank().
     * Add or remove titles here as the clan's rank structure changes.
     */
    private static final String[] ADMIN_TITLE_NAMES = {
            "owner",
            "deputy owner",
            "moderator",
            "sheriff"
    };

    /**
     * Retry interval in milliseconds (5 seconds).
     */
    private static final long RETRY_INTERVAL_MS = 5000;

    /**
     * Maximum retry duration in milliseconds (1 minute).
     */
    private static final long MAX_RETRY_DURATION_MS = 60000;

    @Inject
    private Client client;

    @Inject
    private BoomerangBanditsConfig config;

    private Boolean cachedValidationResult = null;
    private long lastValidationAttempt = 0;
    private long firstFailureTime = 0;
    private boolean hasGivenUp = false;

    /**
     * Validate that the local player is in the Boomerang Bandits clan
     * with sufficient rank.
     * <p>
     * Throttled: After initial failure, retries every 5 seconds for 1 minute, then gives up.
     *
     * @return true if the player is a valid clan member, false otherwise
     */
    public boolean validate() {
        long now = System.currentTimeMillis();

        // If we've already validated successfully, return cached result
        if (cachedValidationResult != null && cachedValidationResult) {
            return true;
        }

        // If we've given up trying, return false immediately
        if (hasGivenUp) {
            return false;
        }

        // Throttle validation attempts - only check every 5 seconds
        if (now - lastValidationAttempt < RETRY_INTERVAL_MS) {
            return cachedValidationResult != null ? cachedValidationResult : false;
        }

        lastValidationAttempt = now;

        // Perform actual validation
        boolean result = performValidation();

        if (result) {
            // Success! Cache it and reset failure tracking
            cachedValidationResult = true;
            firstFailureTime = 0;
            hasGivenUp = false;
            log.info("Clan validation successful");
            return true;
        }

        // Validation failed
        if (firstFailureTime == 0) {
            firstFailureTime = now;
            log.debug("Clan validation failed - will retry every 5s for 1 minute");
        } else if (now - firstFailureTime > MAX_RETRY_DURATION_MS) {
            // We've been trying for over a minute, give up
            hasGivenUp = true;
            log.warn("Clan validation failed after 1 minute of retries - giving up");
        }

        cachedValidationResult = false;
        return false;
    }

    /**
     * Reset validation state (call on logout or clan change).
     */
    public void reset() {
        cachedValidationResult = null;
        lastValidationAttempt = 0;
        firstFailureTime = 0;
        hasGivenUp = false;
    }

    /**
     * Perform the actual validation logic.
     */
    private boolean performValidation() {
        if (client.getGameState() != GameState.LOGGED_IN) {
            return false;
        }

        ClanChannel clanChannel = client.getClanChannel();
        if (clanChannel == null) {
            log.debug("Not in a clan channel");
            return false;
        }

        String currentClanName = clanChannel.getName();
        if (currentClanName == null || !currentClanName.equalsIgnoreCase(CLAN_NAME)) {
            log.debug("In wrong clan: {} (expected {})", currentClanName, CLAN_NAME);
            return false;
        }

        if (client.getLocalPlayer() == null) {
            return false;
        }

        String playerName = client.getLocalPlayer().getName();
        ClanChannelMember member = clanChannel.findMember(playerName);
        if (member == null) {
            log.debug("Could not find self in clan channel");
            return false;
        }

        ClanRank rank = member.getRank();
        if (rank == null || rank.getRank() < MINIMUM_CLAN_RANK) {
            log.debug("Insufficient clan rank: {}", rank);
            return false;
        }

        return true;
    }

    /**
     * Get the current player's clan rank.
     *
     * @return ClanRank or null if not in the clan
     */
    public ClanRank getCurrentRank() {
        ClanChannel clanChannel = client.getClanChannel();
        if (clanChannel == null || client.getLocalPlayer() == null) {
            log.debug("[ClanValidator] getCurrentRank() - No clan channel or local player");
            return null;
        }

        String playerName = client.getLocalPlayer().getName();
        ClanChannelMember member = clanChannel.findMember(playerName);

        if (member == null) {
            log.debug("[ClanValidator] getCurrentRank() - Player '{}' not found in clan channel", playerName);
            return null;
        }

        ClanRank rank = member.getRank();
        log.trace("[ClanValidator] getCurrentRank() for '{}': rank={}, rankValue={}",
                playerName, rank, rank != null ? rank.getRank() : "null");

        return rank;
    }

    /**
     * Check if the player has admin-level rank.
     * Purely title-name based — matches against ADMIN_TITLE_NAMES using
     * the custom title from ClanSettings. No numeric rank ID checks.
     *
     * @return true if the player's clan title is in the admin list
     */
    public boolean isAdmin() {
        ClanRank rank = getCurrentRank();
        if (rank == null) {
            log.debug("[ClanValidator] isAdmin() - rank is null (not in clan channel yet)");
            return false;
        }

        ClanSettings clanSettings = client.getClanSettings();
        if (clanSettings == null) {
            log.debug("[ClanValidator] isAdmin() - ClanSettings not loaded yet");
            return false;
        }

        ClanTitle title = clanSettings.titleForRank(rank);
        if (title == null || title.getName() == null) {
            log.debug("[ClanValidator] isAdmin() - no title for rank {}", rank.getRank());
            return false;
        }

        String titleName = title.getName().toLowerCase().trim();
        for (String adminTitle : ADMIN_TITLE_NAMES) {
            if (titleName.equals(adminTitle)) {
                log.debug("[ClanValidator] isAdmin() - matched admin title '{}'", titleName);
                return true;
            }
        }

        log.debug("[ClanValidator] isAdmin() - title '{}' not in admin list", titleName);
        return false;
    }
}

package com.boomerangbandits.util;

import lombok.Getter;

/**
 * Utility class for throttling refresh operations.
 *
 * <p>Prevents excessive API calls or UI updates by enforcing a minimum
 * time interval between refresh operations. Thread-safe.</p>
 *
 * <p>Usage example:</p>
 * <pre>
 * private final RefreshThrottler throttler = new RefreshThrottler(30_000); // 30 seconds
 *
 * public void refresh() {
 *     if (!throttler.shouldRefresh()) {
 *         return; // Too soon, skip refresh
 *     }
 *
 *     // Perform refresh operation
 *     fetchData();
 *
 *     throttler.recordRefresh(); // Update last refresh time
 * }
 *
 * public void forceRefresh() {
 *     throttler.reset(); // Clear throttle
 *     refresh();
 * }
 * </pre>
 */
@Getter
public class RefreshThrottler {

    /**
     * -- GETTER --
     * Get the configured cooldown period.
     *
     */
    private final long cooldownMs;
    /**
     * -- GETTER --
     * Get the timestamp of the last refresh.
     *
     */
    private volatile long lastRefreshTime;

    /**
     * Create a new refresh throttler with the specified cooldown period.
     *
     * @param cooldownMs minimum time in milliseconds between refreshes
     * @throws IllegalArgumentException if cooldownMs is negative
     */
    public RefreshThrottler(long cooldownMs) {
        if (cooldownMs < 0) {
            throw new IllegalArgumentException("Cooldown must be non-negative");
        }
        this.cooldownMs = cooldownMs;
        this.lastRefreshTime = 0;
    }

    /**
     * Check if enough time has passed since the last refresh.
     *
     * <p>This method does NOT update the last refresh time. Call
     * {@link #recordRefresh()} after successfully completing the refresh.</p>
     *
     * @return true if refresh should proceed, false if still in cooldown
     */
    public boolean shouldRefresh() {
        return System.currentTimeMillis() - lastRefreshTime >= cooldownMs;
    }

    /**
     * Record that a refresh has occurred.
     * Updates the last refresh time to the current time.
     */
    public void recordRefresh() {
        lastRefreshTime = System.currentTimeMillis();
    }

    /**
     * Reset the throttler, allowing an immediate refresh.
     * Useful for "force refresh" operations.
     */
    public void reset() {
        lastRefreshTime = 0;
    }

    /**
     * Get the time remaining until the next refresh is allowed.
     *
     * @return milliseconds until next refresh, or 0 if refresh is allowed now
     */
    public long getTimeUntilNextRefresh() {
        long elapsed = System.currentTimeMillis() - lastRefreshTime;
        long remaining = cooldownMs - elapsed;
        return Math.max(0, remaining);
    }

    /**
     * Check if a refresh is currently in cooldown.
     *
     * @return true if in cooldown (refresh not allowed), false otherwise
     */
    public boolean isInCooldown() {
        return !shouldRefresh();
    }

}

package com.boomerangbandits;

import com.boomerangbandits.api.AuthHeaderInterceptor;
import com.google.inject.AbstractModule;
import com.google.inject.Provides;
import com.google.inject.Singleton;
import java.io.File;
import okhttp3.Cache;
import okhttp3.OkHttpClient;

import javax.inject.Named;

/**
 * Guice module for the Boomerang Bandits plugin.
 * <p>
 * Provides a plugin-scoped {@link OkHttpClient} that wraps RuneLite's shared
 * client with {@link AuthHeaderInterceptor}. All plugin services should inject
 * {@code @Named("boomerang") OkHttpClient} so auth headers are added automatically.
 */
public class BoomerangBanditsModule extends AbstractModule {

    @Override
    protected void configure() {
        bind(AuthHeaderInterceptor.class).in(Singleton.class);
    }

    @Provides
    @Singleton
    @Named("boomerang")
    OkHttpClient provideBoomerangHttpClient(OkHttpClient base, AuthHeaderInterceptor interceptor) {
        return base.newBuilder()
                .addInterceptor(interceptor)
                .build();
    }

    @Provides
    @Singleton
    @Named("boomerangWom")
    OkHttpClient provideBoomerangWomHttpClient(@Named("boomerang") OkHttpClient base) {
        File cacheDir = new File(new File(System.getProperty("user.home"), ".runelite"), "boomerang-bandits-http-cache");
        if (!cacheDir.exists()) {
            cacheDir.mkdirs();
        }

        return base.newBuilder()
                .cache(new Cache(cacheDir, 2L * 1024L * 1024L))
                .build();
    }
}
